/*******************************************************************//**
PURPOSE: AssertValid() Test reporting static labels
***********************************************************************/
SmAssertReportLabel sAssertDerivSurfDefinition_list[] =
{
/*  1 */  {SM_AT_SIZE,    _T("Sample Points"),       _T("m_lNumSamples is greater than zero") },
/*  2 */  {SM_AT_ANGLE,   _T("Sweep"),               _T("End values are between -360 and 360") },
/*  3 */  {SM_AT_POINTER, _T("NULL"),                _T("m_pTangentReference is nonNull when m_eTangencyType == SM_TT_G1_FROM_CURVE or SM_TT_DIR_TO_REFERENCE_CURVE") },
/*  4 */  {SM_AT_SIZE,    _T("Cross-Tangent"),       _T("m_dStartTanLength and m_dEndTanScale are zero or positive") },
/*  5 */  {SM_AT_ANGLE,   _T("Rotation"),            _T("m_dStartAngleDeg and m_dEndAngleDeg are between -360 and 360") },
/*  6 */  {SM_AT_VECTOR,  _T("Vector"),              _T("m_vVector is initialized") },
/*  7 */  {SM_AT_TYPE,    _T("Curvature Type"),      _T("Requested CurvatureType matches BaseCurve or SurfaceBoundaryCurve construction choice") },
/*  8 */  {SM_AT_SIZE,    _T("Radius of Curvature"), _T("m_dStartRadius and m_dEndRadScale are zero or positive") },
/*  9 */  {SM_AT_POINTER, _T("NULL"),                _T("m_pCurvatureReference is non-NULL when m_eCurvatureType == SM_CT_G2_FROM_CURVE") }
} ;

/*******************************************************************//**
PURPOSE: AsserT Valid SmDerivSrfDefinition class.

RETURNS ---  TRUE  = OK
             FALSE = Problem
***********************************************************************/
SmBoolean SmDerivSurfDefinition::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL]
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests,
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests
                                    //      default:[SM_LEVEL_0]
  SmAssertWalking    eWalkTree,     // NotUsed: in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK]
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{
  SM_REF1(eWalkTree) ;
  SM_REF1(pTestRequests);

  // init return
  SmBoolean bRtn = TRUE ;

  // Building from a basecurve or a surface boundary curve
  SmBoolean bBaseCurve = (   m_eTangencyType == SM_TT_G1_FROM_CURVE
                          || m_eTangencyType == SM_TT_ALONG_VECTOR
                          || m_eTangencyType == SM_TT_PERPENDICULAR_TO_VECTOR
                          || m_eTangencyType == SM_TT_PARALLEL_TO_CURVATURE
                          || m_eTangencyType == SM_TT_PERPENDICULAR_TO_CURVATURE) ? TRUE : FALSE ;

  // enough sample points
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (m_lNumSamples >= 1), _T("") ) ;

  // m_dStartDerivDirAngleDeg --| only used when m_eTangencyType == SM_TT_TAN_TO_EDGES,
  // m_dEndDerivDirAngleDeg   --|             or m_eTangencyType == SM_TT_MATCH_NEIGHBORS,
  // can be any value, but let's limit it to +/-360 degrees
  bRtn &= SM_ASSERT_VALUE_REPORT(1, SM_LEVEL_0,
                                (   (   m_eTangencyType != SM_TT_TAN_TO_EDGES
                                     && m_eTangencyType != SM_TT_MATCH_NEIGHBORS)
                                 || (   SM_IS_CONTAINED(m_dStartDerivDirAngleDeg,-360.0, 360.0)
                                     && SM_IS_CONTAINED(m_dEndDerivDirAngleDeg  ,-360.0, 360.0) ) ),
                                SM_EFF_ZERO, (m_dStartDerivDirAngleDeg < -360.0 || m_dStartDerivDirAngleDeg > 360.0)
                                            ? m_dStartDerivDirAngleDeg
                                            : m_dEndDerivDirAngleDeg, 
                                _T("")  ) ;

  // CrossTangent reference
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(2, SM_LEVEL_0, (   (   bBaseCurve == TRUE
                                                       && m_eTangencyType == SM_TT_G1_FROM_CURVE
                                                       && m_pTangentReference)
                                                   || (   bBaseCurve == FALSE
                                                       && m_eTangencyType == SM_TT_DIR_TO_REFERENCE_CURVE
                                                       && m_pTangentReference)
                                                   || (m_pTangentReference == NULL)), 
                                                  _T("") );

  // CrossTangent length interpolation
  bRtn &= SM_ASSERT_VALUE_REPORT(3, SM_LEVEL_0, (m_dStartTanLength >= 0.0 && m_dEndTanScale >= 0.0 ), 0.0, smos_Max(m_dStartTanLength, m_dEndTanScale), _T("") );

  // Rotate angles about basecurve can be any value, but let's limit it to +/-360 degrees
  bRtn &= SM_ASSERT_VALUE_REPORT(4, SM_LEVEL_0,
                                (   SM_IS_CONTAINED(m_dStartAngleDeg,-360.0, 360.0)
                                 && SM_IS_CONTAINED(m_dEndAngleDeg  ,-360.0, 360.0)),
                                SM_EFF_ZERO, (m_dStartAngleDeg < -360.0 || m_dStartAngleDeg > 360.0)
                                            ? m_dStartAngleDeg
                                            : m_dEndAngleDeg, 
                                _T("") );

  // m_vVector value
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(5, SM_LEVEL_0, (  (   m_eTangencyType != SM_TT_ALONG_VECTOR
                                                      && m_eTangencyType != SM_TT_PERPENDICULAR_TO_VECTOR)
                                                   || m_vVector.IsInitialized()), 
                                                  _T("") );

  // curvature type
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(6, SM_LEVEL_0, (   (   bBaseCurve == TRUE
                                                       && (   m_eCurvatureType == SM_CT_G2_FROM_CURVE
                                                           || m_eCurvatureType == SM_CT_FROM_PARAMETERS))
                                                   || (   bBaseCurve == FALSE
                                                       && (   m_eCurvatureType == SM_CT_G2_FROM_SURFACE
                                                           || m_eCurvatureType == SM_CT_G3_FROM_SURFACE))
                                                   || (m_eCurvatureType == SM_CT_NO_CURVATURE)), 
                                                  _T("") );

  // Dvv lengths
  bRtn &= SM_ASSERT_VALUE_REPORT(7, SM_LEVEL_0, (m_dStartRadius >= 0.0 && m_dEndRadScale >= 0.0 ), 0.0, smos_Max(m_dStartRadius, m_dEndRadScale), _T("") );

  bRtn &= SM_ASSERT_BOOLEAN_REPORT(8, SM_LEVEL_0, (   m_eCurvatureType != SM_CT_G2_FROM_CURVE
                                                   || m_pCurvatureReference), 
                                                  _T("") ) ;

  // all done
  return(bRtn) ;

} // end SmDerivSurfDefinition::AssertValid

/*******************************************************************//**
PURPOSE: Create a DerivSurface representing positions, cross-tangents,
      and possibly higher order cross-derivatives along the length of a
      basecurve following the methodology specified by the flags in this
      SmDerivSurfDefiniton object.

NOTES:
  1. The values of a DerivSurface are found from v = 0 isoparameter evaluations as
      D = position
      Dv = 1st cross-deriv
      Dvv = 2nd cross-deriv
      Dvvv = 3rd cross-deriv

  2. Only builds a DerivativeSurface when the m_eTangencyType is set
                to one of the values that builds cross-tangent values from
                curve evaluations as:
     SM_TT_G1_FROM_CURVE              // let cross-tangent dir = TangentReferencePoint - CurvePoint
     SM_TT_ALONG_VECTOR               // let cross-tangent dir = given m_vVector
     SM_TT_PERPENDICULAR_TO_VECTOR    // let cross-tangent dir = perp to CurveNormal and given m_vVector
     SM_TT_PARALLEL_TO_CURVATURE      // let cross-tangent dir = CurveNormal
     SM_TT_PERPENDICULAR_TO_CURVATURE // let cross-tangent dir = CurveBiNormal

  3. rotate tangent vectors about base curve with m_dStartAngleDeg and m_dEndAngleDeg

  4. set 1stDeriv lengths with either m_dStartLength and m_dEndTanScale, or
       as the offset distance between the baseCurve and the m_pTangentReference curve.

  5. Set curvature values with m_CurvatureType.
        SM_CT_NO_CURVATURE    = Dvv values will be zero
        SM_CT_G2_FROM_CURVE   = mag(Dvv) = Dist(BaseCurve(s),CurvatureRef(s))
        SM_CT_FROM_PARAMETERS = mag(Dvv) = LinearInterp(StartRadius,EndRadius)

     and use the m_bFlipCurvature flag to negate the curvature direction

  6. Construction control summary
     m_lNumSamples + 1             = number of curve sample evaluations evenly spaced in parameter space.
     m_eTangencyType               = choose how the directions of cross-derivatives are computed.
     m_dStartTanLength and
     m_dEndTanScale                = for scaling tangent vector lengths: linear interpolation.
     m_pTangentReference           = set tangent directions and lengths as a vector to a reference curve.
     m_dStartAngleDeg and m_dEndAngleDeg = rotate 1st cross-derivs about base curve.
     m_vVector                     = a target vector used in some cross-deriv direction computations.
     m_eCurvatureType              = request computation of Dvv and choose how to compute its magnitude.
     m_dStartRadius and
     m_dEndRadScale                = bounds for linear sweep of radius of curvature
     m_pCurvatureReference         = compute radius of curvature as a distance to the reference curve.
     m_bFlipCurvature              = negate the curvature direction
***********************************************************************/
SmStatus SmDerivSurfDefinition::CreateDerivativeSurface
  (const SmContext      & crContext,       // in : context for new object construction
   const SmBSplineCurve & rBaseCurve,      // in : boundary for derivative surface
   double                 dTolerance,      // in : 0.0 = interpolate, else approximate
   SmBSplineSurface    *& rpDerivSurface)  // out: Evaluate(u,0) yields D(u,0), Dv(u,0), Dvv(u,0), ...
  const
{
  // init output
  rpDerivSurface = NULL;

  // no work - Tangency types for function SmEdgeuse::CreateDerivativeSurface
  SER_MSG((   m_eTangencyType == SM_TT_G1_FROM_CURVE
           || m_eTangencyType == SM_TT_ALONG_VECTOR
           || m_eTangencyType == SM_TT_PERPENDICULAR_TO_VECTOR
           || m_eTangencyType == SM_TT_PARALLEL_TO_CURVATURE
           || m_eTangencyType == SM_TT_PERPENDICULAR_TO_CURVATURE) ? SM_SUCCESS : SM_ERR,
          _T("SmDerivSurfDefinition not set up for construction from base curve")) ;

  // check state
  SER_MSG(AssertValid() ? SM_SUCCESS : SM_ERR, _T("Stored Input Values not Valid")) ;

  // locals
  SmTArray<double>       sParams ;
  SmTArray<SmVector3d>   sPos, s1stDerivs, s2ndDerivs ;
  SmTArray<SmVector3d> * p2ndDerivs =  (   m_eCurvatureType == SM_CT_G2_FROM_CURVE
                                        || m_eCurvatureType == SM_CT_FROM_PARAMETERS)
                                      ? &s2ndDerivs
                                      : NULL ;
  SmTArray<SmBSplineCurve *> sCrossSections ;
  SmObjsDelete<SmBSplineCurve *> sCleanup(&sCrossSections) ;

  // Build D, Dv, Dvv sample value arrays from a BaseCurve
  SER( GetSampleValues(rBaseCurve,
                       sParams,
                       sPos,
                       s1stDerivs,
                       p2ndDerivs) ) ;

  // build cross-section curves from sample values so that
  //  Curve(0) = StartPos, Start1st, . . . and optionally Curve(1) = EndPos, End1st, . . .
  SER( CreateCrossSectionCurves(crContext,
                                sCrossSections,
                                sPos,
                                s1stDerivs,
                                p2ndDerivs) ) ;

  // Build DerivSurface by skinning CrossSection curves
  SER( SkinDerivSurface(crContext,
                         rpDerivSurface,
                         sCrossSections,
                         sParams,
                         rBaseCurve,
                         NULL,
                         dTolerance) ) ;
  // all done
  return(SM_SUCCESS) ;

} // end SmDerivSurfDefinition::CreateDerivativeSurface from a base curve

/*******************************************************************//**
PURPOSE: Create a DerivSurface representing positions, cross-tangents,
      and possibly higher order cross-derivatives along the length of a
      surface boundary curve following the methodology specified by the
      flags in this SmDerivSurfDefiniton object.

NOTES:
  1. The values of a DerivSurface are found from v = 0 isoparameter evaluations as
      D = position
      Dv = 1st cross-deriv
      Dvv = 2nd cross-deriv
      Dvvv = 3rd cross-deriv

  2.) All D position values are computed as rBoundaryCurve evaluations.  Those locations get projected
      to the surface where all Dv, Dvv, . . . values are computed as directional derivative
      values taken from the surface.  The direction of the directional derivative can
      be computed in many different fashions as controlled by the flags of this
      SmDerivSurfDefinition object. So the returned DerivSurface will be C0 with the
      boundary curve and G1/G2/G3 with the surface.

  3.) Currently the DirectionalDeriv direction can vary along the length of the Surface boundary in
      3 manners as specified by m_eTangencyType:
        SM_TT_NO_TANGENCY,           // dir for directionalDerivatives = binormal direction (in or out from surface)
        SM_TT_TAN_TO_EDGES,          // dir for directionalDerivatives = linear interp between given end-UV-tangent vectors
        SM_TT_MATCH_NEIGHBORS,       // dir for directionalDerivatives = linear interp between given end-UV-tangent vectors
        SM_TT_DIR_TO_REFERENCE_CURVE // dir for directionalDerivatives = projection of TangentReferenceCurvePoint-CurvePoint onto surface tangent plane
       There are two cases for the linear option to allow the method SmEdgeUse::CreateDerivativeSurface()
         to set the target end-UV-tangent vectors in various ways.

  4.) Loop Corner management: When creating a sequence of DerivSurfaces for a sequence
      of edges from a loop use the SmEdgeUse::CreateDerivativeSurface() method and
      the SM_TT_MATCH_NEIGHBORS option to make sure that
      the DerivSurfaces end up being water tight with one another at their
      neighbor/neighbor boundaries.

  5.) Construction control summary
     m_lNumSamples + 1             = number of curve sample evaluations evenly spaced in parameter space.
     m_eTangencyType               = choose how the directions of the directional derivatives are computed.
     m_dStartUVTangentAngleDeg and
     m_dEndUVTangentAngleDeg       = set bounds for linear sweep of directional derivatives.
     m_dStartTanLength and
     m_dEndTanScale                = define scaling of take-off vector magnitudes.
     m_pTangentReference           = curve to define take-off vector directions,
     m_dStartAngleDeg and m_dEndAngleDeg = rotate 1st cross-derivs about surface boundary curve
     m_eCurvatureType              = request computation of Dvv and/or Dvvv.
***********************************************************************/
SmStatus SmDerivSurfDefinition::CreateDerivativeSurface
  (const SmContext      & crContext,         // in : Context for new object construction
   const SmSurface      & rSurface,          // in : Target Surface
   const SmBSplineCurve & rBoundaryCurve,    // in : Boundary on that Surface, the closer CurveBoundary is to rSurface the better
   SmExtent1d           & rBoundaryCurveIvl, // in : target Boundary Curve interval
   SmBoolean              bOffToTheRight,    // in : Specify how the tangents come off the curve, When walking along the direction
                                             //      of the curve with one's head in the surface normal's direction,
                                             //      TRUE = Tangents point to the curve's right hand side.
                                             //      FALSE= Tangents point to the curve's left hand side.
   SmBoolean              bStartAtBoundary,  // in : Only used when m_eTangencyType == SM_TT_DIR_TO_REFERENCE_CURVE
                                             //      TRUE = direction dirs selected to start at BoundaryCurve and go to ReferencePt
                                             //      FALSE= direction dirs selected to start at ReferencePt and go to BoundaryCurve
   double                 dTolerance,        // in : 0.0 = interpolate, else approximate
   SmBSplineSurface    *& rpDerivSurface)    // out: The Derivative Surface
  const
{
  // init output
  rpDerivSurface = NULL;

  // no work - Tangency types for function SmEdgeuse::CreateDerivativeSurface
  SER_MSG((   m_eTangencyType == SM_TT_NO_TANGENCY
           || m_eTangencyType == SM_TT_TAN_TO_EDGES
           || m_eTangencyType == SM_TT_MATCH_NEIGHBORS
           || m_eTangencyType == SM_TT_DIR_TO_REFERENCE_CURVE) ? SM_SUCCESS : SM_ERR,
          _T("SmDerivSurfDefinition not set up for construction from Surface Boundary Curve")) ;

  // check state
  SER_MSG(AssertValid() ? SM_SUCCESS : SM_ERR, _T("Stored Input Values not Valid")) ;

  // locals
  SmTArray<double>       sParams ;
  SmTArray<SmVector3d>   sPos, s1stDerivs, s2ndDerivs, s3rdDerivs ;
  SmTArray<SmVector3d> * p2ndDerivs = (m_eCurvatureType == SM_CT_G2_FROM_SURFACE) ? &s2ndDerivs : NULL ;
  SmTArray<SmVector3d> * p3rdDerivs = (p2ndDerivs && m_eCurvatureType == SM_CT_G3_FROM_SURFACE) ? &s3rdDerivs : NULL ;
  SmTArray<SmBSplineCurve *> sCrossSections ;
  SmObjsDelete<SmBSplineCurve *> sCleanup(&sCrossSections) ;

  // Build D, Dv, Dvv sample value arrays from a BaseCurve
  SER( GetSampleValues(rSurface,
                       rBoundaryCurve,
                       rBoundaryCurveIvl,
                       bOffToTheRight,
                       bStartAtBoundary,
                       sParams,
                       sPos,
                       s1stDerivs,
                       p2ndDerivs,
                       p3rdDerivs) ) ;

  // build cross-section curves from sample values so that
  //  Curve(0) = StartPos, Start1st, . . . and optionally Curve(1) = EndPos, End1st, . . .
  // Curves in sCrossSections start at sPos, follow s1stDerivs, p2ndDerivs, etc.
  // If only using s1stDerivs they are tangent lines
  SER( CreateCrossSectionCurves(crContext,
                                sCrossSections,
                                sPos,
                                s1stDerivs,
                                p2ndDerivs,
                                p3rdDerivs) ) ;

  // Build DerivSurface by skinning CrossSection curves
  SER( SkinDerivSurface(crContext,
                         rpDerivSurface,
                         sCrossSections,
                         sParams,
                         rBoundaryCurve,
                         NULL,
                         dTolerance) ) ;
  // all done
  return(SM_SUCCESS) ;

} // end SmDerivSurfDefinition::CreateDerivativeSurface from surface boundary curves

/*******************************************************************//**
PURPOSE: Define pos, cross-tangent, and higher cross-derivative values along
      a BaseCurve at a sequence of evenly parameter-spaced sample points.

NOTES:

  1. Only builds sample points when the m_eTangencyType is set
                to one of the values that builds cross-tangent values from
                curve evaluations as:
     SM_TT_G1_FROM_CURVE              // let cross-tangent dir = TangentReferencePoint - CurvePoint
     SM_TT_ALONG_VECTOR               // let cross-tangent dir = given m_vVector
     SM_TT_PERPENDICULAR_TO_VECTOR    // let cross-tangent dir = perp to CurveNormal and given m_vVector
     SM_TT_PARALLEL_TO_CURVATURE      // let cross-tangent dir = CurveNormal
     SM_TT_PERPENDICULAR_TO_CURVATURE // let cross-tangent dir = CurveBiNormal

  2. rotate tangent vectors about base curve with m_dStartAngleDeg and m_dEndAngleDeg

  3. set 1stDeriv lengths with either m_dStartLength and m_dEndTanScale, or
       as the offset distance between the baseCurve and the m_pTangentReference curve.

  4. Set curvature values with m_CurvatureType.
        SM_CT_NO_CURVATURE    = Dvv values will be zero
        SM_CT_G2_FROM_CURVE   = mag(Dvv) = Dist(BaseCurve(s),CurvatureRef(s))
        SM_CT_FROM_PARAMETERS = mag(Dvv) = LinearInterp(StartRadius,EndRadius)
                                dir(Dvv) = cross(cross-tangent, curve-tangent)

     and use the m_bFlipCurvature flag to negate the curvature direction
***********************************************************************/
SmStatus SmDerivSurfDefinition::GetSampleValues  // from base curve
 (const SmCurve        & rBaseCurve,    // in : target curve
  SmTArray<double>     & rParams,       // out: param along Surface Boundary Curve for every output pos and crossDeriv
  SmTArray<SmVector3d> & rPos,          // out: positions along rBaseCurve
  SmTArray<SmVector3d> & r1stDerivs,    // out: 1stDerivs along rBaseCurve
  SmTArray<SmVector3d> * pOpt2ndDerivs) // out: Opt 2ndDerivs along rBaseCurve, NULL to ignore
                                        //      default:[NULL]
 const
{
  // init output
  rParams.ReSet() ;
  rPos.ReSet() ;
  r1stDerivs.ReSet() ;
  if(pOpt2ndDerivs) pOpt2ndDerivs->ReSet() ;

  // no work - Tangency types for function SmEdgeuse::CreateDerivativeSurface
  SER_MSG((   m_eTangencyType == SM_TT_G1_FROM_CURVE
           || m_eTangencyType == SM_TT_ALONG_VECTOR
           || m_eTangencyType == SM_TT_PERPENDICULAR_TO_VECTOR
           || m_eTangencyType == SM_TT_PARALLEL_TO_CURVATURE
           || m_eTangencyType == SM_TT_PERPENDICULAR_TO_CURVATURE) ? SM_SUCCESS : SM_ERR,
          _T("SmDerivSurfDefinition not set up for construction from base curve")) ;

  // check state
  SER_MSG(AssertValid() ? SM_SUCCESS : SM_ERR, _T("Stored Input Values not Valid")) ;

  // size the outputs
  rParams.SetSize(m_lNumSamples + 1) ;
  rPos.SetSize(m_lNumSamples+1) ;
  r1stDerivs.SetSize(m_lNumSamples+1) ;
  if(pOpt2ndDerivs) pOpt2ndDerivs->SetSize(m_lNumSamples+1) ;

  // locals
  ULONG ii ;
  SmExtent1d sBaseCurveIvl = rBaseCurve.GetNaturalInterval();
  SmVector3d sGVecs[4], sTangentRefPnt, sCurvatureRefPnt ;
  SmVector3d sLastCurvature(0,0,0);

  // for every sample point (+1 for the ends)
  for(ii=0; ii<=m_lNumSamples; ii++)
    {
      double dParam    = (ii < m_lNumSamples) ? (double)ii/(double)m_lNumSamples : 1.0 ;
      double dCrvParam = sBaseCurveIvl.Evaluate(dParam) ;
      rParams.SetAt(ii, dParam) ;

      // evaluate curve: sGVecs[0] = CurvePos,
      //                 sGVecs[1] = CurveTan      (mag=speed),
      //                 sGVecs[2] = CurveCurvature(mag=K,dir=normal),
      //                 sGVecs[3] = CurveTorsion  (mag=torsion,dir=binormal)]
      SER(rBaseCurve.EvaluateGeometric(dCrvParam,3,TRUE,sGVecs));

      // evaluate tangent reference curve when given
      if(m_pTangentReference)
        { SER(m_pTangentReference->EvaluatePoint(dCrvParam,sTangentRefPnt)) ; }

      // evaluate curvature reference curve when given
      if(m_pCurvatureReference && m_eCurvatureType == SM_CT_G2_FROM_CURVE)
        { SER(m_pCurvatureReference->EvaluatePoint(dCrvParam,sCurvatureRefPnt)) ; }

      // negate the curve curvature vector
      sGVecs[2] = - sGVecs[2];

      // preserve continuity of the curvature vector direction
      if (ii>0 && sGVecs[2].Dot(sLastCurvature) < 0.0)
        {
          sGVecs[2] = - sGVecs[2]; // Don't let it flip around after we get started.
        }
      sLastCurvature = sGVecs[2];

      // cross-tangent and cross-curvature vector dirs
      SmVector3d sCrossTangent, sCrossCurvature ;
      switch (m_eTangencyType)
        {
          case SM_TT_G1_FROM_CURVE:              // Cross-tangent direction = Curve BiNormal Vector
                                                 // Cross-curvature         = cross(cross-tangent, Curve Tangent Vector)
                                                 if (m_pTangentReference)
                                                   {
                                                     sCrossTangent   = sTangentRefPnt - sGVecs[0];
                                                     sCrossCurvature = sCrossTangent * sGVecs[1];
                                                   }
                                                 break;

          case SM_TT_ALONG_VECTOR:               // Cross-tangent direction = given vector
                                                 // Cross-curvature         = cross(cross-tangent, Curve Tangent Vector)
                                                 sCrossTangent   = m_vVector;
                                                 sCrossCurvature = sCrossTangent * sGVecs[1];
                                                 break;

          case SM_TT_PERPENDICULAR_TO_VECTOR:    // Cross-tangent direction = component of curvature vec perpendicular to given vector
                                                 // Cross-curvature         = cross(cross-tangent, Curve Tangent Vector)
                                                 smgu_VectorProjectToPlane(sGVecs[2],m_vVector,sCrossTangent);
                                                 sCrossCurvature = sCrossTangent * sGVecs[1];
                                                 break;

          case SM_TT_PARALLEL_TO_CURVATURE:      // Cross-tangent direction = Curve Curvature Vector
                                                 // Cross-curvature         = cross(cross-tangent, Curve Tangent Vector)
                                                 sCrossTangent   = sGVecs[2];
                                                 sCrossCurvature = sCrossTangent * sGVecs[1];
                                                 break;

          case SM_TT_PERPENDICULAR_TO_CURVATURE: // Cross-tangent direction = Curve BiNormal Vector
                                                 // Cross-curvature         = cross(cross-tangent, Curve Tangent Vector)
                                                 sCrossTangent   = sGVecs[3];
                                                 sCrossCurvature = sCrossTangent * sGVecs[1];
                                                 break;

          case SM_TT_NO_TANGENCY:
          case SM_TT_TAN_TO_EDGES:
          case SM_TT_MATCH_NEIGHBORS:
          case SM_TT_DIR_TO_REFERENCE_CURVE: // cases not used here - they're for SmEdgeuse::CreateDerivativeSurface
                                      SER(SM_ERR) ;
              break;
        } // switch on m_eTangencyType to select cross-tangent and cross-curvature directions

      // signal errors when either CrossCurvature or CrossTangent are zero length
      SER(sCrossCurvature.Unitize());
      SER(sCrossTangent.Unitize());

      // cross-tangent length = default: 10.0
      //              if(m_dStartTanLength > 0.0) linearly interpolate given endPoint tangent lengths
      //              if(m_pTangentReference)     set length = dist(CurvePos,TangentReferencePos)
      double dLength =   (m_pTangentReference)     ? sTangentRefPnt.DistanceBetween(sGVecs[0])
                       : (m_dStartTanLength > 0.0) ? (  (1.0 - dParam) * m_dStartTanLength
                                                           + (dParam)  * m_dEndTanScale * m_dStartTanLength)
                       : 10.0 ;
      sCrossTangent = sCrossTangent * dLength;

      // when asked - rotate cross-tangent vector about basecurve
      //              rotAngle = linear interp along curve from m_dStartAngleDeg to m_dEndAngleDeg
      //               GWC note: should we also rotate the CrossCurvature vector.
      SmAxis2Placement sRot;
      double           dRotAngle = m_dStartAngleDeg + dParam * (m_dEndAngleDeg - m_dStartAngleDeg);
      SmVector3d       sAxis     = sGVecs[1];
      sAxis.Unitize();
      sRot.RotateAboutAxis(dRotAngle*SM_PI/180.0,sAxis);
      sRot.TransformPoint(sCrossTangent,sCrossTangent);


      // Radius of curvature: if specified, use the distance to the curvature
      // reference curve, otherwise do a linear interpolation starting at the
      // start radius and scaled by the end radius scale.
      double dRadiusOfCurvature = SM_BIG_DOUBLE;
      if ( m_eCurvatureType == SM_CT_G2_FROM_CURVE && m_pCurvatureReference != NULL )
        {
          SmVector3d sRadVec( sCurvatureRefPnt - sGVecs[0] );

          dRadiusOfCurvature = sRadVec.Length();

          // See if CrossCurvature should be negated.
          if ( sRadVec.Dot( sCrossCurvature ) < 0.0 )
            {
              sCrossCurvature = - sCrossCurvature;
            }
        }
      else if ( m_eCurvatureType == SM_CT_FROM_PARAMETERS )
        {
          dRadiusOfCurvature = (  (1.0 - dParam) * m_dStartRadius
                                + (   dParam   ) * m_dStartRadius * m_dEndRadScale );
        }

      // when asked - negate curvature vector
      if (m_bFlipCurvature)
        {
          sCrossCurvature = - sCrossCurvature;
        }

      // If we assume that the 2nd derivative is the same as the curve's geometric
      // curvature vector we can compute it using the inverse of the geometric.
      SmVector3d sSecondDeriv(0,0,0);
      if ( m_eCurvatureType != SM_CT_NO_CURVATURE )
        { sSecondDeriv = (dLength * dLength / dRadiusOfCurvature) * sCrossCurvature; }

      // set output
      rPos.SetAt(ii, sGVecs[0]) ;
      r1stDerivs.SetAt(ii, sCrossTangent) ;
      if(pOpt2ndDerivs) pOpt2ndDerivs->SetAt(ii, sSecondDeriv) ;

    } // end iter every sample point

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  // draw input surface, boundary curve and output sample points
  if(bDebugMe)
    {
      smgfx_Erase() ;
      smgfx_SetLook(2,3, 0,0,1) ; rBaseCurve.Draw(NULL, TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(2,3, 0,1,0) ; if(m_pTangentReference) m_pTangentReference->Draw(NULL, TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(3,4, 1,0,0) ; for(ii=0;ii<rPos.GetSize();ii++) { rPos[ii].Draw() ; sm_GraphicsLoop() ; }
      smgfx_SetLook(1,2, 1,0,0) ; for(ii=0;ii<rPos.GetSize();ii++) { r1stDerivs[ii].Draw(&rPos[ii]) ; sm_GraphicsLoop() ; }
      smgfx_SetLook(1,2, 1,0,0) ; if(pOpt2ndDerivs) for(ii=0;ii<rPos.GetSize();ii++) { pOpt2ndDerivs->GetAt(ii).Draw(&rPos[ii]) ; sm_GraphicsLoop() ; }
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done
  return(SM_SUCCESS) ;

} // end SmDerivSurfDefinition::GetSampleValues  from BaseCurve

/*******************************************************************//**
PURPOSE: Create and return a BSplineCurve whose values are the
 DerivSurf position values for all valid u values.

NOTES:
***********************************************************************/
SmStatus SmDerivSurfDefinition::ExtractPosCurve
 (SmContext        & rContext,          // in : context for new object construction
  SmBSplineSurface & rDerivSurface,     // in : DerivSurface - probably made by one of the methods of this class
  SmBSplineCurve  *& rpPosCurve)        // out: New BSplineCurve whose values are the positions
                                        //      of the Deriv Surface for all valid u values.
                                        //      The output is allocated in this function and must be deleted by the caller
                                        //      rpPosCurve should equal NULL on input
{
  // check input
  WARN(_T("SmDerivSurfDefinition::ExtractPosCurve: Output pointer rpPosCurve value not NULL on input")) ;

  // init output
  rpPosCurve = NULL ;

  // the position curve is the v=0 isoParamCurve for the rDerivSurface
  return( rDerivSurface.CreateIsoParametricCurve
                         (rContext,         // in : context for created objects
                          SM_SP_V,          // in : SM_SP_U = create constant u isoParameter curve
                                            //      SM_SP_V = create constant v isoParameter curve
                          0.0,              // in : parameter value
                          0.0,              // in : Not Used by this method
                          rpPosCurve) ) ;   // out: The position curve for this DerivSurface

} // end SmDerivSurfDefinition::ExtractPosCurve

/*******************************************************************//**
PURPOSE: Create and return a BSplineCurve whose values are the
 DerivSurf CrossDeriv values for all valid u values.

NOTES:
***********************************************************************/
SmStatus SmDerivSurfDefinition::ExtractCrossDerivCurve
 (SmContext &rContext,                  // in : context for new object construction
  SmBSplineSurface & rDerivSurface,     // in : DerivSurface - probably made by one of the methods of this class
  SmBSplineCurve *& rpCrossDerivCurve)  // out: New BSplineCurve showe values are the positions
                                        //      of the Deriv Surface for all valid u values.
                                        //      The output is allocated in this function and must be deleted by the caller
                                        //      rpPosCurve should equal NULL on input
{
  // check input
  WARN(_T("SmDerivSurfDefinition::ExtractCrossDerivCurve: Output pointer rpCrossDerivCurve value not NULL on input")) ;

  // init output
  rpCrossDerivCurve = NULL ;

  // the CrossDeriv curve is the v=0 CrossDerivative isoParamCurve for the rDerivSurface
  // the position curve is the v=0 isoParamCurve for the rDerivSurface
  return( rDerivSurface.CreateIsoParametricDerivCurve
                         (rContext,                // in : context for created objects
                          0, 1,                    // in : lDerCnt_U and lDerCnt_V, i.e. dW/dv
                          SM_SP_V,                 // in : SM_SP_U = create constant u isoParameter curve
                                                   //      SM_SP_V = create constant v isoParameter curve
                          0.0,                     // in : parameter value
                          0.0,                     // in : Not Used by this method
                          rpCrossDerivCurve) ) ;   // out: The position curve for this DerivSurface

} // end SmDerivSurfDefinition::ExtractCrossDerivCurve

/*******************************************************************//**
PURPOSE: Create and return a BSplineCurve whose values are the
 DerivSurf Cross2ndDeriv values for all valid u values.

NOTES:
***********************************************************************/
SmStatus SmDerivSurfDefinition::Extract2ndDerivCurve
 (SmContext &rContext,                     // in : context for new object construction
  SmBSplineSurface & rDerivSurface,        // in : DerivSurface - probably made by one of the methods of this class
  SmBSplineCurve *& rpCross2ndDerivCurve)  // out: New BSplineCurve showe values are the positions
                                           //      of the Deriv Surface for all valid u values.
                                           //      The output is allocated in this function and must be deleted by the caller
                                           //      rpPosCurve should equal NULL on input
{
  // check input
  WARN(_T("SmDerivSurfDefinition::Extract2ndDerivCurve: Output pointer rpCross2ndDerivCurve value not NULL on input")) ;

  // init output
  rpCross2ndDerivCurve = NULL ;

  // the CrossDeriv curve is the v=0 CrossDerivative isoParamCurve for the rDerivSurface
  // the position curve is the v=0 isoParamCurve for the rDerivSurface
  return( rDerivSurface.CreateIsoParametricDerivCurve
                         (rContext,                   // in : context for created objects
                          0, 2,                       // in : lDerCnt_U and lDerCnt_V, i.e. dW/dv
                          SM_SP_V,                    // in : SM_SP_U = create constant u isoParameter curve
                                                      //      SM_SP_V = create constant v isoParameter curve
                          0.0,                        // in : parameter value
                          0.0,                        // in : Not Used by this method
                          rpCross2ndDerivCurve) ) ;   // out: The position curve for this DerivSurface

} // end SmDerivSurfDefinition::Extract2ndDerivCurve

/*******************************************************************//**
PURPOSE: Define pos, cross-tangent, and higher cross-derivative values along
      a surface boundary curve at a sequence of evenly parameter-spaced sample points.

NOTES:
  1.) The D, Dv, Dvv, and Dvvv values along a surface boundary curve are sampled in
      even parameter steps where,
         D = position
         Dv = 1st cross-deriv
         Dvv = 2nd cross-deriv
         Dvvv = 3rd cross-deriv

  2.) All D values are set by rBoundaryCurve evaluations.  Those locations get projected
      to the surface where all Dv, Dvv, . . . values are computed as directional derivative
      values taken from the surface.  The direction of the directional derivative can
      be computed in many different fashions as controlled by the flags of this
      SmDerivSurfDefinition object. So the returned DerivSurface will be C0 with the
      boundary curve and G1/G2/G3 with the surface.

  3.) Currently the DirectionalDeriv direction can vary along the length of the
      Surface boundary curve in three manners as specified by m_eTangencyType:
        SM_TT_NO_TANGENCY,           // dir for directionalDerivatives = binormal direction (in or out from surface)
        SM_TT_TAN_TO_EDGES,          // dir for directionalDerivatives = linear interp between given end-UV-tangent vectors
        SM_TT_MATCH_NEIGHBORS,       // dir for directionalDerivatives = linear interp between given end-UV-tangent vectors
        SM_TT_DIR_TO_REFERENCE_CURVE // dir for directionalDerivatives = projection of TangentReferenceCurvePoint-CurvePoint onto surface tangent plane
       There are two cases for the linear option to allow the method SmEdgeUse::CreateDerivativeSurface()
         to set the target end-UV-tangent vectors in various ways.  Read Note below for
         case SM_TT_DIR_TO_REFERENCE_CURVE.

  4.) Loop Corner management: When creating a sequence of DerivSurfaces for a sequence
      of edges from a loop use the SmEdgeUse::CreateDerivativeSurface() method and
      the SM_TT_MATCH_NEIGHBORS option to make sure that
      the DerivSurfaces end up being water tight with one another at their
      neighbor/neighbor boundaries.

  5.) Construction control summary
     m_lNumSamples + 1             = number of curve sample evaluations evenly spaced in parameter space.
     m_eTangencyType               = choose how the directions of the directional derivatives are computed.
     m_dStartUVTangentAngleDeg and
     m_dEndUVTangentAngleDeg       = set bounds for linear sweep of directional derivatives.
     m_dStartTanLength and
     m_dEndTanScale                = bounds for linear sweep of tangent vector gains applied to 1st crossDeriv.
     m_pTangentReference           = set tangent directions
     m_dStartAngleDeg and m_dEndAngleDeg = rotate 1st cross-derivs about surface boundary curve
     m_eCurvatureType              = request computation of Dvv and/or Dvvv.

  note: when building a blend from one curve to another using
        the SM_TT_DIR_TO_REFERENCE_CURVE option a reasonable choice for the
        cross-derivative directions is to project the vector from this curve to
        the reference curve to the surface tangency plane and use that to pick the direction.
        This works well for blends that run pretty much from one edge to the other
        whithout folding.  To generalize the approach a bit reflect the the reference
        point about a plane defined by the surface normal and the curve tangent when the the
        reference point is on the opposite side of the plane from the take off side of the
        desired cross tangent.  This approach now works for blend boundaries that are lined
        up and/or folded about an axis that runs mostly parallel to the target blend edges.
        This does not work well for complicated cases where the reference curve point ends
        up being near the curve tangency direction or when a sequence of curve sample points
        cross the reflection plance. If cases like this come up we will have to try yet another
        approach for defining the blend iso-parameter step off directions.

***********************************************************************/
SmStatus SmDerivSurfDefinition::GetSampleValues   // from surface boundary curve
  (const SmSurface   & rSurface,          // in : target surface
   const SmCurve     & rBoundaryCurve,    // in : Boundary on that Surface, the closer CurveBoundary is to rSurface the better
   SmExtent1d        & rBoundaryCurveIvl, // in : Target Boundary Curve interval
   SmBoolean           bOffToTheRight,    // in : Specify how the tangents come off the curve, When walking along the direction
                                          //      of the curve with one's head in the surface normal's direction,
                                          //      TRUE = Tangents point to the curve's right hand side.
                                          //      FALSE= Tangents point to the curve's left hand side.
   SmBoolean           bStartAtBoundary,  // in : Only used when m_eTangencyType == SM_TT_DIR_TO_REFERENCE_CURVE
                                          //      TRUE = direction dirs selected to start at BoundaryCurve and go to ReferencePt
                                          //      FALSE= direction dirs selected to start at ReferencePt and go to BoundaryCurve
   SmTArray<double>     & rParams,        // out: param along Surface Boundary Curve for every output pos and crossDeriv
   SmTArray<SmVector3d> & rPos,           // out: positions
   SmTArray<SmVector3d> & r1stDerivs,     // out: cross1stDerivs
   SmTArray<SmVector3d> * pOpt2ndDerivs,  // out: cross2ndDerivs, NULL to ignore, default:[NULL]
   SmTArray<SmVector3d> * pOpt3rdDerivs)  // out: cross3rdDerivs, NULL to ignore, default:[NULL]
  const
{
  // init output
  rParams.ReSet() ;
  rPos.ReSet() ;
  r1stDerivs.ReSet() ;
  if(pOpt2ndDerivs) { pOpt2ndDerivs->ReSet() ; }
  if(pOpt3rdDerivs) { pOpt3rdDerivs->ReSet() ; }

  // no work - Tangency types for function SmEdgeuse::CreateDerivativeSurface
  SER_MSG((   m_eTangencyType == SM_TT_NO_TANGENCY
           || m_eTangencyType == SM_TT_TAN_TO_EDGES
           || m_eTangencyType == SM_TT_MATCH_NEIGHBORS
           || m_eTangencyType == SM_TT_DIR_TO_REFERENCE_CURVE) ? SM_SUCCESS : SM_ERR,
          _T("SmDerivSurfDefinition not set up for construction from Surface Boundary Curve")) ;

  // check state
  SER_MSG(AssertValid() ? SM_SUCCESS : SM_ERR, _T("Stored Input Values not Valid")) ;

  // size the output
  rParams.SetSize(m_lNumSamples + 1) ;
  rPos.SetSize(m_lNumSamples + 1) ;
  r1stDerivs.SetSize(m_lNumSamples + 1) ;
  if(pOpt2ndDerivs) { pOpt2ndDerivs->SetSize(m_lNumSamples + 1) ; }
  if(pOpt3rdDerivs) { pOpt3rdDerivs->SetSize(m_lNumSamples + 1) ; }

  // locals
  ULONG  ii ;
  SmVector3d sSurfacePV[2] ;  // sSurfacePV[0] = 3d Surface Point closest to Curve Point
                              // sSurfacePV[1] = 3d dir vector defining surface directional derivatives
  SmVector2d sSurfaceUV[2] ;  // sSurfaceUV[0] = 3d Surface UVPoint closest to Curve Point
                              // sSurfaceUV[1] = dir of Surface DirectionalDerivatives which define cross-deriv values
  SmVector2d sUVGuess ;
  SmVector3d sReferencePnt ;
  SmVector3d sReferenceGap ;
  double     dReferenceGap = 0.0;
  double     dScaledZero = 0.0;

  // get number of cross-derivatives to compute and set lDegree for a bezier curve to interpolate those values
  ULONG lNumDerivatives =   pOpt3rdDerivs ? 3
                          : pOpt2ndDerivs ? 2
                          :                 1 ;
  // ULONG lDegree         = lNumDerivatives * 2 + 1 ;

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
      // draw binormal, surface normal and curveTangent in current image
      if(bDebugMe)
        {
          smgfx_Erase() ;
          smgfx_SetLook(3,4, 0,0,1) ; rBoundaryCurve.Draw(&rBoundaryCurveIvl) ; sm_GraphicsLoop() ;
          smgfx_SetLook(2,3, 0,1,0) ; if(m_pTangentReference) m_pTangentReference->Draw() ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,1,1) ; rSurface.Draw(TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,1,1) ; rSurface.DrawUV() ; sm_GraphicsLoop() ;
          sm_GraphicsLoop() ;
        }
#endif // SM_DEBUG_CODE

  // for every sample point (+ 1 for the ends)
  for ( ii=0; ii<=m_lNumSamples; ii++ )
    {
      double dParam    = (ii < m_lNumSamples) ? (double)ii/(double)m_lNumSamples : 1.0 ;
      double dCrvParam = rBoundaryCurveIvl.Evaluate(dParam);
      rParams.SetAt(ii, dCrvParam) ;

      // BoundaryCurve pos and tan
      SmVector3d sBoundaryCurvePV[2] ; // sBoundaryCurvePV[0] = rBoundaryCurve 3dPoint    for param = dCrvParam
                                       // sBoundaryCurvePV[1] = rBoundaryCurve 3dTangent  for param = dCrvParam
      SER(rBoundaryCurve.Evaluate(dCrvParam, 1, TRUE, sBoundaryCurvePV, FALSE));   // exact tangent values

      // insist on non-degenerate curves
      dScaledZero = SM_EFF_ZERO * (1.0 + rBoundaryCurveIvl.GetLength()) ;
      SER_MSG(sBoundaryCurvePV[1].LengthSquared() > dScaledZero ? SM_SUCCESS : SM_ERR,
              _T("DerivSurface not defined for degenerate Curves")) ;

      // project CurvePoint to Surface, sSurfacePV[0] = CurvePoint dropped to Surface
      //                                sSurfacePV[1] = Direction of directional derivative that defines
      //                                                the cross-deriv output values
      SmBoolean  bSuccess = FALSE ;
      double     dGap ;
      SmBoolean bIsMulti;
      SER_MSG((SM_SUCCESS == rSurface.DropPoint(sBoundaryCurvePV[0],
                                                rSurface.GetNaturalUVDomain(),
                                                ii == 0 ? NULL : &sUVGuess,
                                                bSuccess,
                                                sSurfaceUV[0],
                                                dGap,
                                                bIsMulti)
               && bSuccess) ? SM_SUCCESS : SM_ERR,
              _T("Curve Point Failed to Drop to Surface UVPoint")) ;
      sUVGuess = sSurfaceUV[0] ;

      // Surface Normal
      SmVector3d sSurfaceNormal ;
      SER_MSG(rSurface.EvaluateNormal(sSurfaceUV[0], TRUE, TRUE, sSurfaceNormal),
              _T("Failed to evaluate a Surface Normal at a Surface point")) ;
      SER_MSG(sSurfaceNormal.LengthSquared() > SM_EFF_ZERO ? SM_SUCCESS : SM_ERR,
              _T("DerivSurface not defined for degenerate Surfaces")) ;
      sSurfaceNormal.Unitize() ;

      // Surface Boundary Binormal
      SmVector3d sBoundaryBinormal =   bOffToTheRight
                                     ? sBoundaryCurvePV[1] * sSurfaceNormal
                                     : sSurfaceNormal * sBoundaryCurvePV[1] ;
      double dBiLength = sBoundaryBinormal.Length() ;
      dScaledZero = SM_EFF_ZERO * (1.0 + sBoundaryCurvePV[1].GetMaxDimension()) ;
      SER_MSG(dBiLength > dScaledZero ? SM_SUCCESS : SM_ERR,
              _T("Boundary Curves can not be perpendicular to Surface")) ;
      sBoundaryBinormal /= dBiLength ;

#ifdef SM_DEBUG_CODE
      // draw binormal, surface normal and curveTangent in current image
      if(bDebugMe)
        {
          smgfx_SetLook(3,4, 0,0,1) ; sBoundaryCurvePV[0].Draw() ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 1,0,0) ; sBoundaryBinormal.Draw(&sBoundaryCurvePV[0]) ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,1,0) ; sBoundaryCurvePV[1].Draw(&sBoundaryCurvePV[0]) ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 1,0,1) ; sSurfaceNormal.Draw(&sBoundaryCurvePV[0]) ; sm_GraphicsLoop() ;
          sm_GraphicsLoop() ;
        }
#endif // SM_DEBUG_CODE


      // switch on m_eTangencyType to pick the directional derivative direction - stored in sSurfacePV[1]
      switch(m_eTangencyType)
        {
          // note: Formerly forced closed curves to use the SM_TT_NO_TANGENCY option.
          //       If removing this behavior causes problems - consider replacing it here.
          case SM_TT_NO_TANGENCY:
            {
              // 3d dir = +/- boundary 3d binormal direction
              sSurfacePV[1] = sBoundaryBinormal ;

              // 2d dir = projection of 3d binormal into surface UV space
              rSurface.ComputeParamDirection(sSurfaceUV[0], sBoundaryBinormal, sSurfaceUV[1]) ;
              sSurfaceUV[1].Unitize() ;
            }
          break ;

          case SM_TT_TAN_TO_EDGES   :
          case SM_TT_MATCH_NEIGHBORS:
            {
              // dir = linear interp between m_dStartDerivDirAngleDeg and m_dEndDerivDirAngleDeg
              if ( bOffToTheRight == TRUE )
                { sBoundaryBinormal = - sBoundaryBinormal ; }

              // Project BoundaryBinormal to SurfaceUV
              SmVector2d sBoundaryUVBinormal ;
              SER_MSG ( rSurface.ComputeParamDirection( sSurfaceUV[0],
                                                        sBoundaryBinormal,
                                                        sBoundaryUVBinormal),
                                                        _T("Curve Tangent Failed to Drop to Surface UVTangent")) ;
              sBoundaryUVBinormal.Unitize() ;

              // linearly interp the dir rotation angle
              double dAngRad = SM_DEG2RAD(  (1.0 - dParam) * m_dStartDerivDirAngleDeg
                                          + (   dParam   ) * m_dEndDerivDirAngleDeg) ;

              // set directional derivative direction
              sSurfaceUV[1] = sBoundaryUVBinormal.Rotate(dAngRad) ;
            }
          break ;

          case SM_TT_DIR_TO_REFERENCE_CURVE :
            // dir = projection of TangentReferenceCurvePoint-CurvePoint onto surface tangent plane
            // note: when building a blend from one curve to another a
            //       reasonable choice for the cross-derivative directions is to
            //       project the vector from this curve to the reference curve
            //       to the surface tangency plane and use that to pick the direction.
            //       This works well for blends that run pretty much from one edge
            //       to the other whithout folding.  To generalize the approach a bit
            //       reflect the the reference point about a plane defined by the
            //       surface normal and the curve tangent when the the reference point
            //       is on the opposite side of the plane from the take off side of the
            //       desired cross tangent.  This approach now works for blend boundaries
            //       that are lined up and/or folded about an axis that runs mostly parallel
            //       to the target blend edges.  This does not work well for complicated
            //       cases where the reference curve point ends up being near the
            //       curve tangency direction.  If cases like this come up we will have
            //       to try yet another approach.
            {
              // reference point
              SER(m_pTangentReference->EvaluatePoint(dCrvParam, sReferencePnt)) ;
              sReferenceGap = sReferencePnt - sBoundaryCurvePV[0] ;
              dReferenceGap = sReferenceGap.Length() ;
              dScaledZero = SM_EFF_ZERO * (1.0 + sReferencePnt.GetMaxDimension()) ;
              SER_MSG(dReferenceGap > dScaledZero ? SM_SUCCESS : SM_ERR,
                         _T("Reference Curve can not intersect Surface Boundary Curve")) ;

              // Positive Dist = reference gap in same direction as 1st cross-deriv
              double dDist = sReferenceGap.Dot(sBoundaryBinormal) ;

              // when starting at the boundary
              if(bStartAtBoundary)
                {
                  // and reference pnt is behind the curve -
                  //   mirror refPnt about plane perp to binormal and choose start dir
                  //   to move towards that point.
                  if(dDist < 0.0)
                    { sReferencePnt = sReferencePnt + 2.0 * -dDist * sBoundaryBinormal ; }
                  else
                    { // choose start dir to move towards current RefPnt location - do nothing ;
                    }
                  sReferenceGap = sReferencePnt - sBoundaryCurvePV[0] ;
                } // end starting at boundary curve branch
              else // when starting at ref curve
                {
                  // and reference pnt is in front of the curve -
                  // choose directional derivative dir to move in the (Mirror(RefPnt)-BoundaryCrv) direction
                  if(dDist > 0.0)
                    { sReferencePnt = sReferencePnt + 2.0 * -dDist * sBoundaryBinormal ; }
                  else
                    { // choose directional derivative dir to move in the (RefPnt-BoundaryCrv) direction
                    }
                  sReferenceGap = sBoundaryCurvePV[0] - sReferencePnt ;
                } // end starting at ref curve branch

              // Project sGap into Surface UV plane
              rSurface.ComputeParamDirection(sSurfaceUV[0], sReferenceGap, sSurfaceUV[1]) ;
              sSurfaceUV[1].Unitize() ;
#ifdef SM_DEBUG_CODE
              // draw
              if(bDebugMe)
                {
                  SmVector3d sTestValues[4], sInitRefPnt(sReferencePnt) ;
                  rSurface.EvaluateDirectionalDerivs(sSurfaceUV[0], sSurfaceUV[1], 3, sTestValues) ;
                  if(   ( bStartAtBoundary && dDist < 0.0)
                     || (!bStartAtBoundary && dDist > 0.0))
                    { sInitRefPnt = sReferencePnt + 2.0 * dDist * sBoundaryBinormal ; }

                  // add evals to current image
                  smgfx_SetLook(3,4, 1,0,0) ; sInitRefPnt.Draw() ; sm_GraphicsLoop() ;
                  smgfx_SetLook(3,4, 1,0,0) ; sReferencePnt.Draw() ; sm_GraphicsLoop() ;
                  smgfx_SetLook(3,4, 0,0,1) ; sBoundaryCurvePV[0].Draw() ; sm_GraphicsLoop() ;
                  smgfx_SetLook(1,2, 0,1,1) ; sReferenceGap.Draw(&sBoundaryCurvePV[0]) ; sm_GraphicsLoop() ;
                  smgfx_SetLook(1,2, 1,0,0) ; sBoundaryBinormal.Draw(&sBoundaryCurvePV[0]) ; sm_GraphicsLoop() ;
                  smgfx_SetLook(1,2, 0,0,1) ; sTestValues[1].Draw(&sBoundaryCurvePV[0]) ; sm_GraphicsLoop() ;
                  sm_GraphicsLoop() ;
                }
#endif // SM_DEBUG_CODE
            }
          break ;


          default: SER_MSG(SM_ERR, _T("Unsupported construction case in SmDerivSurfDefinition::GetSampleValues(), bad input")) ;

        } // end switch on m_eTangencyType to pick the dirDerivative direction


      // Surface directional derivatives up to the num of derivs being stored
      SmVector3d sTgtValues[4] ;  // [pos, 1st Deriv, 2nd Deriv, 3rd Deriv]
      sTgtValues[0].Set(0,0,0) ;
      sTgtValues[1].Set(0,0,0) ;
      sTgtValues[2].Set(0,0,0) ;
      sTgtValues[3].Set(0,0,0) ;
      rSurface.EvaluateDirectionalDerivs(sSurfaceUV[0], sSurfaceUV[1], lNumDerivatives, sTgtValues) ;

      // Do not support degenerate surfaces
      double dTgt1stDerivLength = sTgtValues[1].Length() ;
      dScaledZero = SM_EFF_ZERO * (1.0 * sTgtValues[0].GetMaxDimension()) ;
      SER_MSG(dTgt1stDerivLength > dScaledZero ? SM_SUCCESS : SM_ERR,
              _T("Surface Evaluation has a zero length tangent vector - DerivSurfaces to degenerate surfaces not supported")) ;
      // GWC note: This last check seems too tight.  SMLib could support a DerivSurf whose tangents go to zero at some point.

      // let positions = Curve Positions
      sTgtValues[0] = sBoundaryCurvePV[0] ;

      // tangent length - 1. default = mag(Directional 1st-Derivativate)
      //                  2. when asked, linearly interp two given end lengths
      //                  3. when asked, scale by dist( BoundaryCurve(s), TangentReference(s) )
      double dTanLength = -1.0;
      if ( m_dStartTanLength > 0.0 )
        {
          // Linearly interpolate according to m_dStartTanLength and m_dEndTanScale.
          dTanLength =   (1.0 - dParam) * m_dStartTanLength
                       + (  dParam    ) * m_dEndTanScale * m_dStartTanLength;
        }
      if ( m_pTangentReference != NULL )
        { dTanLength *= dReferenceGap; }

      // Change tangent length when not using the current length
      if ( dTanLength > 0.0 )
        {
          sTgtValues[1] = sTgtValues[1] * dTanLength / dTgt1stDerivLength ;
        }

      // When asked Rotate Tangent about BaseCurve by Ang
      //   Ang = Linearly interp between given end values
      double dRotAngleDeg = m_dStartAngleDeg + dParam * (m_dEndAngleDeg - m_dStartAngleDeg);
      if(   sBoundaryCurvePV[1].Unitize() == SM_SUCCESS
         && smos_Fabs( dRotAngleDeg ) > SM_EFF_ZERO )
        {
          SmAxis2Placement sRot;
          sRot.RotateAboutAxis(SM_DEG2RAD(dRotAngleDeg), sBoundaryCurvePV[1]);
          sRot.TransformPoint(sTgtValues[1], sTgtValues[1]);

          // GWC note: should we be rotating the 2nd and 3rd deriv vectors as well?
          //           Wait until we get a user request.
        }

      // set outputs
      rPos.SetAt(ii, sTgtValues[0]) ;
      r1stDerivs.SetAt(ii, sTgtValues[1]) ;
      if(pOpt2ndDerivs) { pOpt2ndDerivs->SetAt(ii, sTgtValues[2]) ; }
      if(pOpt3rdDerivs) { pOpt3rdDerivs->SetAt(ii, sTgtValues[3]) ; }

    } // end iter every sample point

#ifdef SM_DEBUG_CODE
  // draw input surface, boundary curve and output sample points
  if(bDebugMe)
    {
      smgfx_Erase() ;
      smgfx_SetLook(1,2, 0,1,1) ; rSurface.Draw(TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 0,1,1) ; rSurface.DrawUV() ; sm_GraphicsLoop() ;
      smgfx_SetLook(2,3, 0,0,1) ; rBoundaryCurve.Draw(NULL, TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(2,3, 0,0,1) ; rBoundaryCurve.Draw(&rBoundaryCurveIvl) ; sm_GraphicsLoop() ;
      smgfx_SetLook(2,3, 0,1,0) ; if(m_pTangentReference) m_pTangentReference->Draw(NULL, TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(3,4, 1,0,0) ; for(ii=0;ii<rPos.GetSize();ii++) { rPos[ii].Draw() ; sm_GraphicsLoop() ; }
      smgfx_SetLook(1,2, 1,0,0) ; for(ii=0;ii<rPos.GetSize();ii++) { r1stDerivs[ii].Draw(&rPos[ii]) ; sm_GraphicsLoop() ; }
      smgfx_SetLook(1,2, 1,0,0) ; if(pOpt2ndDerivs) for(ii=0;ii<rPos.GetSize();ii++) { pOpt2ndDerivs->GetAt(ii).Draw(&rPos[ii]) ; sm_GraphicsLoop() ; }
      smgfx_SetLook(1,2, 1,0,0) ; if(pOpt3rdDerivs) for(ii=0;ii<rPos.GetSize();ii++) { pOpt3rdDerivs->GetAt(ii).Draw(&rPos[ii]) ; sm_GraphicsLoop() ; }
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done
  return(SM_SUCCESS) ;

} // end SmDerivSurfDefinition::GetSampleValues  for Surface boundary curves

/*******************************************************************//**
PURPOSE: Build an array of cross-section curves with specified
    begin position and derivative values and optional end position and
    derivative values.

NOTES: This is mostly a convenience routine that takes the
  output of the SmDerivSurfDefinition::GetSampleValues to build
  a family of interpolting curves that can be used as cross-sections
  which can be skinned to become a DerivSurface.

  This function can also be used to build cross sections which control
  both the start and end position tangents.  This is helpful
  for some blend functions which use these capabilities to build
  blends between G1/G2G3 end targets.
***********************************************************************/
SmStatus SmDerivSurfDefinition::CreateCrossSectionCurves
  (const SmContext            & crContext,           // in : context for new object construction
   SmTArray<SmBSplineCurve *> & rCrossSections,      // out: array of new SmBSpline bezier curves with Ivls = [0,1]
   SmTArray<SmVector3d>       & rStartPos,           // in : start position
   SmTArray<SmVector3d>       & rStart1stDerivs,     // in : start 1st deriv
   SmTArray<SmVector3d>       * pOptStart2ndDerivs,  // in : optional start 2nd deriv, NULL to ignore
   SmTArray<SmVector3d>       * pOptStart3rdDerivs,  // in : optional start 3rd dervi, NULL to ignore
   SmTArray<SmVector3d>       * pOptEndPos,          // in : optional end position
   SmTArray<SmVector3d>       * pOptEnd1stDerivs,    // in : optional end 1st deriv
   SmTArray<SmVector3d>       * pOptEnd2ndDerivs,    // in : optional end 2nd deriv
   SmTArray<SmVector3d>       * pOptEnd3rdDerivs)    // in : optional end 3rd deriv
 const
{
  // init output
  rCrossSections.ReSet() ;
  SmObjsDelete<SmBSplineCurve *> sCleanup( &rCrossSections ) ;

  // check state - Values only on the start side or the same number of values on both sides
  //               All lesser derivative values of the max derivative must be given
  //               All arrays must have the same size

  // size constraint
  SER((rStartPos.GetSize() == rStart1stDerivs.GetSize()) ? SM_SUCCESS : SM_ERR) ;
  SER((pOptStart2ndDerivs == NULL || pOptStart2ndDerivs->GetSize() == rStartPos.GetSize()) ? SM_SUCCESS : SM_ERR) ;
  SER((pOptStart3rdDerivs == NULL || pOptStart3rdDerivs->GetSize() == rStartPos.GetSize()) ? SM_SUCCESS : SM_ERR) ;

  SER((pOptEndPos         == NULL || pOptEndPos->GetSize()         == rStartPos.GetSize()) ? SM_SUCCESS : SM_ERR) ;
  SER((pOptEnd1stDerivs   == NULL || pOptEnd1stDerivs->GetSize()   == rStartPos.GetSize()) ? SM_SUCCESS : SM_ERR) ;
  SER((pOptEnd2ndDerivs   == NULL || pOptEnd2ndDerivs->GetSize()   == rStartPos.GetSize()) ? SM_SUCCESS : SM_ERR) ;
  SER((pOptEnd3rdDerivs   == NULL || pOptEnd3rdDerivs->GetSize()   == rStartPos.GetSize()) ? SM_SUCCESS : SM_ERR) ;

  // lesser derivative constraint
  SER((pOptStart3rdDerivs == NULL || pOptStart2ndDerivs != NULL) ? SM_SUCCESS : SM_ERR) ;

  SER((pOptEnd3rdDerivs   == NULL || pOptEnd2ndDerivs != NULL)   ? SM_SUCCESS : SM_ERR) ;
  SER((pOptEnd2ndDerivs   == NULL || pOptEnd1stDerivs != NULL)   ? SM_SUCCESS : SM_ERR) ;
  SER((pOptEnd1stDerivs   == NULL || pOptEndPos != NULL)         ? SM_SUCCESS : SM_ERR) ;

  // just start or matching end and start value constraints
  SER(   (pOptEnd3rdDerivs  == NULL  && pOptStart3rdDerivs == NULL)
      || (pOptEnd3rdDerivs  != NULL  && pOptStart3rdDerivs != NULL) ? SM_SUCCESS : SM_ERR) ;
  SER(   (pOptEnd2ndDerivs  == NULL  && pOptStart2ndDerivs == NULL)
      || (pOptEnd2ndDerivs  != NULL  && pOptStart2ndDerivs != NULL) ? SM_SUCCESS : SM_ERR) ;

  // start pos and 1st deriv are always required - just require end pos when end 1st derivs are given
  SER(   (pOptEnd1stDerivs  == NULL  && pOptEndPos == NULL)
      || (pOptEnd1stDerivs  != NULL  && pOptEndPos != NULL) ? SM_SUCCESS : SM_ERR) ;

  // Size output
  rCrossSections.SetSize(rStartPos.GetSize()) ;
  rCrossSections.SetAll(NULL) ;

  // pick crossSection degree high enough to interpolate all the given end values
  ULONG lNumDerivatives =   pOptStart3rdDerivs ? 3
                          : pOptStart2ndDerivs ? 2
                          :                    1 ;
  ULONG lDegree         = lNumDerivatives * 2 + 1 ;

  // CreateInterpolatingCurve() locals
  ULONG ii ;
  SmTArray<SmPoint3d>  sTgtPnts ;   sTgtPnts.SetSize(2) ;
  SmTArray<SmVector3d> sTgt1sts ;   sTgt1sts.SetSize(2) ;
  SmTArray<SmVector3d>       sTgtHigher ;
  if(lNumDerivatives == 3) { sTgtHigher.SetSize(4) ; }
  else                     { sTgtHigher.SetSize(2) ; }
  SmPoint3d sC(0,0,0), sD(0,0,0) ;

  // for every sample input
  for(ii=0;ii<rStartPos.GetSize();ii++)
    {
      // shuffle start input for CreateInterpolatingCurve() call
      sTgtPnts.SetAt(0, rStartPos[ii]) ;
      sTgt1sts.SetAt(0, rStart1stDerivs[ii]) ;
      if(pOptStart2ndDerivs) sTgtHigher.SetAt(0, pOptStart2ndDerivs->GetAt(ii)) ;
      if(pOptStart3rdDerivs) sTgtHigher.SetAt(2, pOptStart3rdDerivs->GetAt(ii)) ;

      // pick end input for CreateInterpoltingCurve() call
      // 1. From input option end values, or
      // 2. From Evaluations of taylor series expansion for given start inputs at s = 1.0 values

      if(pOptEndPos == NULL)
        {
          // Compute end points using 1st, 2nd, or 3rd degree taylor series approximation
          //   taylor seriesfor CrossSection(s) for s:[0,1]
          //    CrossSectionCurve(s) =   CrossSection(0)
          //                           + CrossSection'(0)*s
          //                           + CrossSection''(0)*ss/2.0
          //                           + CrossSection'''(0)*sss/6.0 ;

          // get high order taylor series coefficients
          if(pOptStart2ndDerivs) sC = pOptStart2ndDerivs->GetAt(ii) ;
          if(pOptStart3rdDerivs) sD = pOptStart2ndDerivs->GetAt(ii) ;

          // Compute CrossSection(s) for s = 1
          sTgtPnts.SetAt  (1, rStartPos[ii] + rStart1stDerivs[ii] + sC/2.0 + sD/6.0) ;
          sTgt1sts.SetAt  (1, rStart1stDerivs[ii] + sC + sD/2.0) ;
          if(pOptStart2ndDerivs) sTgtHigher.SetAt(1, sC + sD) ;
          if(pOptStart3rdDerivs) sTgtHigher.SetAt(3, sD) ;
        }
      else // given end values
        {
          sTgtPnts.SetAt  (1, pOptEndPos->GetAt(ii)) ;
          sTgt1sts.SetAt  (1, pOptEnd1stDerivs->GetAt(ii)) ;
          if(pOptEnd2ndDerivs) sTgtHigher.SetAt(1, pOptEnd2ndDerivs->GetAt(ii)) ;
          if(pOptEnd3rdDerivs) sTgtHigher.SetAt(3, pOptEnd3rdDerivs->GetAt(ii)) ;
        }

      // build an interpolating curve that equals target values at Curve(0) evaluations
      SmBSplineCurve *pBSplineCurve = NULL ;
      SER(SmBSplineCurve::CreateInterpolatingCurve
                (crContext,                                  // in : context for new object construction
                 SM_CP_UNIFORM,                              // in : parameterization option
                 3,                                          // in : result dimension
                 lDegree,                                    // in : result degree
                 sTgtPnts,                                   // in : Target points
                 sTgt1sts,                                   // in : Start and End Tangents
                 lNumDerivatives >= 2 ? &sTgtHigher : NULL,  // in : Optionally, Start and End 2nd and 3rd derivative vectors
                 FALSE,                                      // in : FALSE = respect Vector Magnitudes
                 pBSplineCurve)) ;                           // out: the approximating BSpline

      // build array of curves and parameters
      rCrossSections.SetAt(ii, pBSplineCurve);

    } // end iter every sample point

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  // draw
  if(bDebugMe)
    {
      SmVector3d sStartTgt[4],  sEndTgt[4] ;
      SmVector3d sStartTest[4], sEndTest[4] ;

      // test curve
      for(ii=0;ii<rStartPos.GetSize();ii++)
        {
          sStartTgt[0] = rStartPos[ii] ;
          sStartTgt[1] = rStart1stDerivs[ii] ;
          if(pOptStart2ndDerivs) sStartTgt[2] = pOptStart2ndDerivs->GetAt(ii) ;
          if(pOptStart3rdDerivs) sStartTgt[3] = pOptStart3rdDerivs->GetAt(ii) ;

          if(pOptEndPos)       sEndTgt[0] = pOptEndPos->GetAt(ii) ;
          if(pOptEnd1stDerivs) sEndTgt[1] = pOptEnd1stDerivs->GetAt(ii) ;
          if(pOptEnd2ndDerivs) sEndTgt[2] = pOptEnd2ndDerivs->GetAt(ii) ;
          if(pOptEnd3rdDerivs) sEndTgt[3] = pOptEnd3rdDerivs->GetAt(ii) ;

          rCrossSections[ii]->Evaluate(0.0, lNumDerivatives, TRUE, sStartTest, FALSE) ; // exact tangent values
          rCrossSections[ii]->Evaluate(1.0, lNumDerivatives, TRUE, sEndTest, FALSE) ;   // exact tangent values

          for(ULONG jj=0;jj<=lNumDerivatives;jj++)
            {
              // check that the correct information has been encoded into the curve
              double dStartGap   = (sStartTest[jj] - sStartTgt[jj]).Length() ;
              double dScaledZero = SM_EFF_ZERO * 100.0 * (1.0 + smos_Max(sStartTest[jj].GetMaxDimension(),
                                                                 sStartTgt[jj].GetMaxDimension())) ;
              SE_MSG(SM_IS_ZERO_TO_TOL(dStartGap, dScaledZero) ? SM_SUCCESS : SM_ERR, _T("DerivSurface crossSection bad start value")) ;

              if(pOptEndPos)
                {
                  double dEndGap     = (sEndTest[jj] - sEndTgt[jj]).Length() ;
                  dScaledZero = SM_EFF_ZERO * 100.0 * (1.0 + smos_Max(sEndTest[jj].GetMaxDimension(),
                                                                      sEndTgt[jj].GetMaxDimension())) ;
                  SE_MSG(SM_IS_ZERO_TO_TOL(dEndGap, dScaledZero) ? SM_SUCCESS : SM_ERR, _T("DerivSurface crossSection bad end value")) ;
                }
            }
        } // end iter every sample point for testing

      // draw curve
      smgfx_Erase() ;
      for(ii=0;ii<rStartPos.GetSize();ii++)
        {
          smgfx_SetLook(1,2, 0,1,0) ; rCrossSections[ii]->Draw() ; sm_GraphicsLoop() ;
          smgfx_SetLook(3,4, 0,1,1) ; rStartPos[ii].Draw() ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,1,1) ; rStart1stDerivs[ii].Draw(&rStartPos[ii]) ; sm_GraphicsLoop() ;

          smgfx_SetLook(3,4, 0,0,1) ; if(pOptEndPos) pOptEndPos->GetAt(ii).Draw() ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,0,1) ;
          if(pOptEnd1stDerivs) {
              SmVector3d vect = pOptEndPos->GetAt(ii);
              pOptEnd1stDerivs->GetAt(ii).Draw(&vect) ;
              sm_GraphicsLoop() ;
          }
          sm_GraphicsLoop() ;
        }
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done
  sCleanup.Clear() ;
  return(SM_SUCCESS) ;

} // end SmDerivSurfDefinition::CreateCrossSectionCurves

/*******************************************************************//**
PURPOSE: Convenience function to build DerivSurf from CrossSection
    curves built by CreateCrossSecionCurves method.

NOTES:
***********************************************************************/
SmStatus SmDerivSurfDefinition::SkinDerivSurface
 (const SmContext            & crContext,         // in : context for new object construction
  SmBSplineSurface          *& rpDerivSurface,    // out: The skinned surface
  SmTArray<SmBSplineCurve *> & sCrossSections,    // in : array of cross-sections to skin
  SmTArray<double>           & sParams,           // in : param value for every cross-section
  const SmBSplineCurve       & rStartRailCurve,   // in : Surface iso-parameter curve running through all sCrossSection start points
  const SmBSplineCurve       * pOptEndRailCurve,  // in : Optional Surface iso-parameter curve running through all sCrossSection end points
                                                  //      NULL to ignore, default:[NULL]
  double                       dTolerance)        // in : 0.0 = interpolate cross-sections, else approximate
                                                  //      default:[0.0]
 const
{
  // init output
  rpDerivSurface = NULL ;

  // CreateSkinnedSurface locals
  ULONG lDegree     =   pOptEndRailCurve
                      ? smos_Max(rStartRailCurve.GetDegree(), pOptEndRailCurve->GetDegree())
                      : rStartRailCurve.GetDegree() ;

  // set skinned surface start/end cross-tangent derivative constraints.
  // note: This can be confusing when working with DerivSurfaces because the
  //       cross-derivative information running 1st, 2nd, and 3rd degree derivatives
  //       is stored in the shape of the cross-section curves.  The skin-shaped
  //       ends need only be good to C0 where it connects up to the target curve shape.
  SmBSplineSurface * pDerivSurf[2] ;
  pDerivSurf[0]     = NULL;  // NULL = ignore skin surface start cross-derivative constraint
  pDerivSurf[1]     = NULL;  // NULL = ignore skin surface start cross-derivative constraint

  // sweep the set of sample curves to make the derivative surface
  //     note: The TangentSurface V=0 isoParameter curve has
  //              the pos, cross-tangent, and higherorder cross-derivative values to
  //              be used to specify a blend to this edgeuse's surface
  SER(SmBSplineSurface::CreateSkinnedSurface
         (crContext,        // in : context for new geometry construction
          sCrossSections,   // in : CrossSectionCurves in order of occurrence on surface
          TRUE,             // in : TRUE    = CrossSectionCurves have same degree and are synchronized
          SM_SP_U,          // in : SM_SP_U = CrossSectionCurves become surface U isoparameter curves.
                            //      SM_SP_V = CrossSectionCurves become surface V isoparameter curves.
          dTolerance,       // in : 0.0 = skinning interpolates cross sections,
                            //      else skinning approximates CrossSectionCurves.
          &rStartRailCurve, // in : Min param sideBoundary curve of surface. Null to ignore.
          pOptEndRailCurve, // in : Max param sideBoundary curve of surface. Null to ignore.
                            //      If both rails are specified they must be syncronized.
          FALSE,            // in : TRUE = use pRail1 as spine curve.  All CrossSectionCurves
                            //      should be positioned along the spine curve at given parameter
                            //      values specified by pIntersectionsWithRails.
          &sParams,         // in : Rail parameters of CrossSectionCurve/Rail intersections.
          pDerivSurf,       // in : pDerivSurf[0] = skinned surface start CrossBoundary derivatives. NULL to ignore.
                            //      pDerivSurf[1] = skinned surface end CrossBoundary derivatives. NULL to ignore.
          rpDerivSurface,   // out: The skinned surface
          lDegree)) ;       // in : sweep direction degree, default:[3]

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE;
  if (bDebugMe)
    {
      ULONG ii ;

      // dump BaseCurve, tangent reference, and output Derivative surface
      rStartRailCurve.Dump();
      if (pOptEndRailCurve) pOptEndRailCurve->Dump();
      rpDerivSurface->Dump();

      smgfx_Erase();
      smgfx_SetLook(2,3, 0,0,1) ; rStartRailCurve.Draw(); sm_GraphicsLoop();
      smgfx_SetLook(2,3, 0,1,1) ; if (pOptEndRailCurve) pOptEndRailCurve->Draw();  sm_GraphicsLoop();
      smgfx_SetLook(1,2, 0,1,0) ; for(ii=0;ii<sCrossSections.GetSize();ii++)
                                    { sCrossSections[ii]->Draw() ; sm_GraphicsLoop() ; }
      smgfx_SetLook(1,2, 1,0,0) ; rpDerivSurface->Draw(TRUE); sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 1,0,0) ; rpDerivSurface->DrawUV(10,10); sm_GraphicsLoop() ;

      smgfx_SetLook(1,2, 1,0,1) ; rpDerivSurface->DrawAlong(SM_SP_V, 0.0, 1); sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 1,0,1) ; rpDerivSurface->DrawAlong(SM_SP_V, 0.0, 2); sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 1,0,1) ; rpDerivSurface->DrawAlong(SM_SP_V, 0.0, 3); sm_GraphicsLoop() ;

      smgfx_SetLook(1,2, 1,0,1) ; rpDerivSurface->DrawAlong(SM_SP_V, 1.0, 1); sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 1,0,1) ; rpDerivSurface->DrawAlong(SM_SP_V, 1.0, 2); sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 1,0,1) ; rpDerivSurface->DrawAlong(SM_SP_V, 1.0, 3); sm_GraphicsLoop() ;
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done
  return SM_SUCCESS;

} // end SmDerivSurfDefinition::SkinDerivSurface

