/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
static const SmSurface * sm_GetOriginalSurface
  (const SmTreeNode & crSurfaceNode)        // in : TreeNode from SurfaceCache
{
  SmTree *pTree = crSurfaceNode.m_pTree;
  if (!pTree->GetOwner()->IsKindOf(SmSurfaceCache_TYPE))
    {
      SE(SM_ERR);  // should never happen
    }
  SmSurfaceCache *pSurfaceCache = (SmSurfaceCache*)pTree->GetOwner();
  if (pSurfaceCache == NULL)
    {
      SE(SM_ERR); // should never happen
    }
  return pSurfaceCache->GetSurface();

} // end sm_GetOriginalSurface

/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
static const SmSurface * sm_GetSurfaceToEvaluate
  (const SmTreeNode * cpSurfaceNode,   // in : 
   const SmSurface  * pBSS)            // NotUsed: in : 
{
  SM_REF1(pBSS) ;
    const SmSurface * pSurf = sm_GetOriginalSurface(*cpSurfaceNode);

    return pSurf;

} // end sm_GetSurfaceToEvaluate

/*******************************************************************//**
PURPOSE: Judge potential solution points

RETURNS --- TRUE = Point should be kept when
                     The point is within TrimBoundaries of a Face
                or   The surface has no Trim boundaries
                or   Point testing has been turned off
                         ( SurfaceCache->m_bPointTestEnabled == FALSE )
            FALSE= Point should be skipped

NOTES:
  Return TRUE when SurfaceNode is part of a SmSurfaceCache and
                   not part of a trimmed surface cache
***********************************************************************/
static SmBoolean sm_IsPointValid
  (const SmTreeNode & crSurfaceNode,       // in : Surface Spatial Decomposition Node
   const SmPoint2d  & crUVPoint,           // in : Point on the surface
   double           * p3dTolerance=NULL,   // in : When not NULL, max allowed distance
                                           //      to count a near misses as a hit
   SmObject        ** pObject=NULL)        // in : optional pointer to topology object coincident with point
                                           //      NULL to ignore, default:[NULL]
{
  // locals
  SmTree         * pTree         = crSurfaceNode.m_pTree;
  SmSurfaceCache * pSurfaceCache = (SmSurfaceCache*)pTree->GetOwner();

  // keep all points when SurfaceNode has no trim boundaries
  if (!pTree->GetOwner()->IsKindOf(SmSurfaceCache_TYPE))
    { return TRUE; }

  // Test Point against surface->Owner TrimBoundaries
  //   when pSurfaceCache is a TrimSrfCache (not a SurfaceCache)
  //            is current
  //        and pSurfaceCache->m_bPointTestEnabled == TRUE
  SmBoolean bRet    = TRUE;
  SmStatus  sStatus = pSurfaceCache->PointTest( crUVPoint, bRet, (SmZoneTol3d*)p3dTolerance, pObject );

  if (sStatus != SM_SUCCESS)
    {
      // Signal errors from the Face->PointClassify() call
      //   and tell the caller to keep the point just in case.
      SE(SM_ERR);
      SM_DBG_WARN(_T("SmSurface.cpp sm_IsPointValid() - passed a point that caused an error in SmFace::PointClassify()") );
      return TRUE;
    }

  // all done
  return bRet;

} // end sm_IsPointValid

/*******************************************************************//**
PURPOSE: When SurfaceCache->m_bPointTestEnabled == TRUE
              determines if a TrimSrfCache node representing one BezPatch
              subDivision of a larger surface can be culled because it
              is known to be outside of its face.

USAGE NOTES --
  Returns TRUE when
   SurfaceCache->m_bPointTestEnabled == FALSE,
   TrimSrfCache node is inside or on its face's boundary, or
   whenever no determination can be made because,
       the cache is not a TrimSrfCache,
       the cache is out of date,
       the face has been modified since the cache was last updated.
***********************************************************************/
static SmBoolean sm_IsNodeValid     // rtn: FALSE=Node is outside of face boundary
                                      //      TRUE =node test is off,
                                      //            node is in/on face boundary
                                      //            or test cannot be made
  (const SmTreeNode & crSurfaceNode)  // in : target node to review
{
  // no work - TreeNode is not part of a SurfaceCache
  SmTree *pTree = crSurfaceNode.m_pTree;
  if (!pTree->GetOwner()->IsKindOf(SmSurfaceCache_TYPE))
    {
      SE(SM_ERR);
      return TRUE;
    }

  // when testing is off or cache is not current
  SmSurfaceCache * pSurfaceCache = (SmSurfaceCache*)pTree->GetOwner();
  if ((   !pSurfaceCache->m_bPointTestEnabled)
       || (pSurfaceCache->m_bFaceWasModified)
       || (!pSurfaceCache->m_bHaveTSurfaceCache))
    {
      // return TRUE so this node won't be culled
      return TRUE;
    }
  else // return FALSE = outside face, TRUE = in/on face
    {
      SmBezierAux2d * pBezAux = (SmBezierAux2d*)crSurfaceNode.m_pData;
      //      if (pBezPatch->m_sAux.m_eNodeClass == SM_NC_OUTSIDE)
      if (pBezAux->m_eNodeClass == SM_NC_OUTSIDE)
        {
          return FALSE;
        }
      return TRUE;
    }

} // end sm_IsNodeValid

