/*******************************************************************//**
PURPOSE: Get Surface's TrimSrfCache if available
            else get Surface's SurfaceCache if available

NOTES:
***********************************************************************/
SmSurfaceCache* smsurf_GetSurfaceCache
  (const SmSurface *cpSurface)
{
  // Mutex for parallel cache manipulation
  // std::lock_guard<std::recursive_mutex> lock((cpSurface->mCacheMutex));
  SmSurfaceCache * pSurfaceCache = NULL ;

  // if possible - get or make TrimSrfCache
  pSurfaceCache = (SmSurfaceCache*)SmCacheMgr::GetOrCreateObjectCache(SM_OC_TRIMSRF, cpSurface);
  // else - get or make SurfaceCache
  if (!pSurfaceCache)
    {
      pSurfaceCache = (SmSurfaceCache*)SmCacheMgr::GetOrCreateObjectCache(SM_OC_SURFACE, cpSurface);
    }

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe  = FALSE ;
SmBoolean bDebugMe1 = FALSE ;
  // draw
  if(bDebugMe1)
    {
      SM_ASSERT_VALID(pSurfaceCache) ;
    }
  if(bDebugMe)
    {
      SmTrimSrfCache * pTrimSurfaceCache = SM_CAST_PTR(SmTrimSrfCache, pSurfaceCache) ;
      if     (pTrimSurfaceCache) pTrimSurfaceCache->Dump() ;
      else if(pSurfaceCache)     pSurfaceCache->Dump() ;

      smgfx_Erase() ;
      smgfx_SetLook(1,2, 0,1,1) ; if(pTrimSurfaceCache) pTrimSurfaceCache->DrawSubdivision2D(TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 1,0,1) ; if(pSurfaceCache)  pSurfaceCache->Draw(TRUE) ; sm_GraphicsLoop() ;
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done
  return pSurfaceCache;

} // end smsurf_GetSurfaceCache

