/*******************************************************************//**
PURPOSE:

// This local function will be an interface to the local solver
// routine.  Allowable operations include SM_SO_MINIMIZE and
// SM_SO_MAXIMIZE.

NOTES:
***********************************************************************/
static void sm_DrawSolution
  (const SmSurface  & crSurface,
   const SmCurve    & crCurve,
   const SmSolution & crSolution,
   SmGfxArraySet    * pOptGfxSet)
{
    sm_GraphicsLoop();
    smgfx_ChangeColor(TRUE, pOptGfxSet);
    SmPoint3d sCrvPnt, sSurfacePoint;
    crCurve.EvaluatePoint(crSolution.m_vStart[0],sCrvPnt);
    crSurface.EvaluatePoint(SmPoint2d(crSolution.m_vStart[1],crSolution.m_vStart[2]),
        sSurfacePoint);
    sCrvPnt.Draw();
    sSurfacePoint.Draw();
    SmVector3d sVec = sCrvPnt - sSurfacePoint;
    sVec.Draw(&sSurfacePoint);
    sm_GraphicsLoop();
} // end sm_DrawSolution

