//                    SmBoolean bSamePoint = smos_Fabs(sLastSolution.m_vStart[0]-rCurrSolution.m_vStart[0]) < SM_EFF_ZERO_SQRT ;
//                    if(bSamePoint)
//                      {
//                        // Check LastSol/ThisSol CurvePoint 3d Distance
//                        SmPoint3d sCurvePoint1, sCurvePoint2 ;
