/*******************************************************************//**
PURPOSE:  Draw and Return a UVPlane upon which UVCurves can
 be drawn in 3d for viewing as if on the 2d unit square.

NOTES: Singular Boundaries are drawn in grey-red
                Seam     Boundaries are drawn in grey-cyan
                other    Boundaries are drawn in grey

  Always Draw the UVPlane icon, optionally add color coded 3d Boundary curves.

***********************************************************************/
SmDisplayList * SmSurface::DrawUVDomain
  (const SmTArray<SmCurve *> * cpOptUVCurves,     // in : Array of UVCurves to Draw in UVPlane 3d icon
                                                  //      default:[NULL]
   const SmExtent2d          * cpOptUVDomain,     // in : Subdomain only used to size UVPlane Graphic size - always draw full surface
                                                  //      ignored when NULL or when pOptUVCurves is given
                                                  //      default:[NULL]
   SmBoolean                   bDraw2dBoundaries, // in : TRUE = Draw 2d UVPlane Icon, FALSE = don't
                                                  //      default:[FALSE]
   SmBoolean                   bDraw3dBoundaries, // in : TRUE = Draw 3d Surface Natural Boundary Curves, FALSE = don't
                                                  //      default:[FALSE]
   SmBoolean                   bAddNormals,       // in : TRUE = draw Normal comb on cpOptUVCurves, FALSE = don't
                                                  //      default:[FALSE]
   double                      dNormalScale,      // in : NormalComb scale factor, 1.0 = Draw Unit Normal Vectors
                                                  //      default:[1.0}
   const SmContext           * cpContext,         // in : context used when allocating rpUVPlane
                                                  //      default:NULL
   SmPlane                  ** ppOptUVPlane,      // out: UVPlane upon which UVTrimCurves can be drawn as a unitSquare icon.
                                                  //      NULL to ignore, default:[NULL]
  SmGfxArraySet              * pOptGfxSet)        // i/o: used for OpenGL ES 2.0. When given, accumulate GfxVertexArrays not GL calls.
                                                  //      NULL to ignore, default:[NULL]
 const
{
  // init output and return
  SmDisplayList *pRtn = NULL ;
  if(ppOptUVPlane && *ppOptUVPlane) { delete *ppOptUVPlane ; *ppOptUVPlane = NULL ; }

#ifdef SM_GFX_CODE
  // check input
  SERN( (   ppOptUVPlane == NULL
         || cpContext != NULL) ? SM_SUCCESS : SM_ERR) ;

  // locals
  ULONG ii ;
  SmContext  sContext ;
  SmPoint3d  sPnt1, sPnt2 ;
  SmPoint2d  sUVPnt1, sUVPnt2 ;
  SmBoolean  bSeam[4]  = { FALSE, FALSE, FALSE, FALSE } ; // UMin, UMax, VMin, VMax
  SmBoolean  bSing[4]  = { FALSE, FALSE, FALSE, FALSE } ; // UMin, UMax, VMin, VMax
  SmExtent2d sUVDomain = this->GetNaturalUVDomain() ;

  // set up the plane memory
  SmObjDelete sCleanPlane(NULL) ;
  SmPoint3d   sOrigin(0,0,0), sNorm(0,0,1) ;
  SmPlane   * pUVPlane = new (cpContext ? *cpContext : sContext) SmPlane(sOrigin, sNorm) ;
  if(ppOptUVPlane) { *ppOptUVPlane = pUVPlane ; }
  else             {  sCleanPlane.SetObj(pUVPlane) ; }

  // classify the surface boundary seams and singularities
  bSeam[0]  = bSeam[1] = this->IsClosed(sUVDomain, SM_SP_U) ;
  bSeam[2]  = bSeam[3] = this->IsClosed(sUVDomain, SM_SP_V) ;
  this->FindSingularities(bSing[0], bSing[1], bSing[2], bSing[3]) ;

  // set up the UVPlane 3d icon surface
    {
      SmExtent2d    sBBoxUV ;
      SmExtent3d    sBBox3d ;
      SmPseudoBox   sPseudoBox ;
      SmSurface   * pCopySurface = NULL ;
      SmObjDelete   sClean(NULL) ;
      double        dUVTol  = sUVDomain.GetMaxDimension() / 100.0 ;

      // Get sBBoxUV for sizing the UVPlane 3d icon
      if(cpOptUVCurves)
        {
          SmExtent3d sThisBox, sUBox ;
          for(ii=0;ii<cpOptUVCurves->GetSize();ii++)
            {
              cpOptUVCurves->GetAt(ii)->CalculateBoundingBox(cpOptUVCurves->GetAt(ii)->GetNaturalInterval(), &sThisBox) ;
              if(ii==0) sUBox = sThisBox ;
              else      sUBox.Union(sThisBox, sUBox) ;
            }
          sBBoxUV.SetMinMax(sUBox.GetUMin(), sUBox.GetVMin(), sUBox.GetUMax(), sUBox.GetVMax()) ;
        }
      else
        {
          sBBoxUV = cpOptUVDomain ? *cpOptUVDomain : sUVDomain ;
        }

      // adjust to optional subdomains - trim a surface copy and work with that for sizing and orienting the plane
      if(!sBBoxUV.AreEqual(sUVDomain, dUVTol)) { // copy and trim surface to given subdomain
                                                 Copy(sContext, pCopySurface) ;
                                                 sClean.SetObj(pCopySurface) ;
                                                 pCopySurface->TrimWithDomain(sBBoxUV) ;
                                               }
      else                                     { // Set CopySurface to point to this
                                                 pCopySurface = (SmSurface *)this ;
                                               }

      // Get the surfaces's bounding boxes
      pCopySurface->CalculateBoundingBox(sBBoxUV, &sBBox3d, &sPseudoBox) ;

      // get a characteristic tangent plane on the surface (use a BBoxUV near the min corner)
      SmVector3d sSrfPt, sSrfDU, sSrfDV ;
      pCopySurface->Evaluate1stDerivatives( sBBoxUV.Evaluate(0.01, 0.01), TRUE, TRUE, sSrfPt, sSrfDU, sSrfDV) ;
      SM_ASSERT(sSrfDU.Length() > SM_EFF_ZERO) ;
      SM_ASSERT(sSrfDV.Length() > SM_EFF_ZERO) ;
      SM_ASSERT((sSrfDU * sSrfDV).Length() > SM_EFF_ZERO) ;
      if(   sSrfDU.Length() < SM_EFF_ZERO
         || sSrfDV.Length() < SM_EFF_ZERO
         || (sSrfDU * sSrfDV).Length() < SM_EFF_ZERO)
        { return(NULL) ; }

      // orient the plane for drawing UVPlane graphics to the pseudo box
      ULONG sIndex[3] = {0, 1, 2} ;
      SmPoint3d sSizes = sPseudoBox.GetIntervalSizes();
      ULONG lTmp = 0;
      double dTmp;
     
      // order the PseudoBox intervals from longest to shortest
      if(sSizes[0] < sSizes[1])
      {
        dTmp = sSizes[0]; sSizes[0] = sSizes[1]; sSizes[1] = dTmp;
        lTmp = sIndex[0]; sIndex[0] = sIndex[1]; sIndex[1] = lTmp;
      }

      if(sSizes[1] < sSizes[2])
      {
        dTmp = sSizes[1]; sSizes[1] = sSizes[2]; sSizes[2] = dTmp;
        lTmp = sIndex[1]; sIndex[1] = sIndex[2]; sIndex[2] = lTmp;
      }

      if(sSizes[0] < sSizes[1])
      {
        dTmp = sSizes[0]; sSizes[0] = sSizes[1]; sSizes[1] = dTmp;
        lTmp = sIndex[0]; sIndex[0] = sIndex[1]; sIndex[1] = lTmp;
      }

      // find a pseudoBox plane that is not perp to surface's characterized surface normal 
      // starting with a TmpPlane oriented with the longest two pseudo box intervals
      SmBoolean bDone = FALSE ;
      SmVector3d sX, sY, sZ, sTmpX, sTmpY ;
      SmVector2d sX2d, sY2d ;
      for(ii = 0; ii < 3 && bDone == FALSE; ii++)
      {
        sTmpX = sPseudoBox.GetBasis( sIndex[0] );
        sTmpY = sPseudoBox.GetBasis( sIndex[1] );

        // unitize and orthogonalize sTmpX and sTmpY
        sTmpX.Unitize();
        sTmpY = sTmpX * sTmpY * sTmpX;
        sTmpY.Unitize();

        // Pick X in the XY TmpPlane so that it lines up with Du
        smgu_VecLinCombTwoVectors( sTmpX, sTmpY, sSrfDU, sX2d );
        smgu_VecLinCombTwoVectors( sTmpX, sTmpY, sSrfDV, sY2d );

        double dX2dLength = sX2d.Length();
        double dY2dLength = sY2d.Length();

        // watch out for a plane oriented perp to the selected pseudoBox plane
        if(SM_IS_ZERO( dX2dLength ) || SM_IS_ZERO( dY2dLength ))
        {
          // try another orientation - rotate the Sizes and the indices
          dTmp = sSizes[2]; sSizes[2] = sSizes[1]; sSizes[1] = sSizes[0]; sSizes[0] = dTmp;
          lTmp = sIndex[2]; sIndex[2] = sIndex[1]; sIndex[1] = sIndex[0]; sIndex[0] = lTmp;

          bDone = FALSE;
        }
        else
        {
          bDone = TRUE;
        }
      } // end iter all possible orientations looking for a plane not perp to surface tangent plane
      
      // when we can't find an orientation for the UVPlane - quit
      if(bDone == FALSE)
        {
          return(NULL) ;
        }

      // orient the selected plane to align with the parameteric surface tangents
      sX = sX2d.x * sTmpX + sX2d.y * sTmpY ;
      sY = sY2d.x * sTmpX + sY2d.y * sTmpY ;

      // unitize and orthogonalize sX and sY and sZ
      sX.Unitize() ;
      sY = sX * sY * sX ;
      sY.Unitize() ;
      sZ = sX * sY ;

      // Set Scale = 1 and place all the plane size in the UVDomain
      SmVector2d sUVScale(sBBoxUV.XLength() > SM_EFF_ZERO ? sSizes[0]/sBBoxUV.XLength() : sSizes[0],
                          sBBoxUV.YLength() > SM_EFF_ZERO ? sSizes[1]/sBBoxUV.YLength() : sSizes[1]) ;

      // offset the plane origin from the min corner in the shortest interval direction
      sOrigin =   sPseudoBox.Evaluate(0,0,0)
                - sX * sUVScale.x * sBBoxUV.GetUMin()
                - sY * sUVScale.y * sBBoxUV.GetVMin()
                + sZ * smos_Max(1.0, sSizes[2]) * 1.3 ;

      // save the plane
      SmAxis2Placement sPosition( sOrigin, sX, sY ) ;
      pUVPlane->SetUVScale(sUVScale) ;
      pUVPlane->SetPosition(sPosition) ;
      pUVPlane->UpdateAnalyticalDomain(sBBoxUV) ;
      pUVPlane->MakeNurb() ;

    } // end setting up the UVPlane icon surface scope

  SmTArray<SmCurve *> sUVCurves ;
  const SmTArray<SmCurve *> * pUVCurves = cpOptUVCurves ? cpOptUVCurves : &sUVCurves ;

  SmVector3d sColor     = smgfx_GetOutputColor(pOptGfxSet) ;
  double     dLineWidth = smgfx_GetOutputLineWidth(pOptGfxSet) ;

  // start new displayList (unless one is already open)
  smgfx_Open(smgfx_GetRuleColor(this), NULL, NULL, FALSE, pOptGfxSet);

  smgfx_OutputLineWidth(dLineWidth, pOptGfxSet) ;

  // when given UVCurves to Draw - Draw them
  for(ii=0;ii<pUVCurves->GetSize();ii++)
    {
      smgfx_ChangeColor(ii != 0, pOptGfxSet) ;
      pUVPlane->DrawUVCurve(*pUVCurves->GetAt(ii), FALSE, 1.0, FALSE, pOptGfxSet) ;
      this->DrawUVCurve(*pUVCurves->GetAt(ii), bAddNormals, dNormalScale, FALSE, pOptGfxSet) ;
    }

  smgfx_SetLineWidth(1, pOptGfxSet) ;

  // render the 4 sides - colored for seams and singularities
  for(ii=0;ii<4;ii++)
    {
      switch(ii)
        { case 0: // UMIN
                  sUVPnt1 = sUVDomain.Evaluate(0,0) ;
                  sUVPnt2 = sUVDomain.Evaluate(0,1) ;
                  pUVPlane->EvaluatePointFast(sUVPnt1,  sPnt1) ;
                  pUVPlane->EvaluatePointFast(sUVPnt2,  sPnt2) ;
                  break ;
          case 1: // UMAX
                  sUVPnt1 = sUVDomain.Evaluate(1,0) ;
                  sUVPnt2 = sUVDomain.Evaluate(1,1) ;
                  pUVPlane->EvaluatePointFast(sUVPnt1,  sPnt1) ;
                  pUVPlane->EvaluatePointFast(sUVPnt2,  sPnt2) ;
                  break ;
          case 2: // VMIN
                  sUVPnt1 = sUVDomain.Evaluate(0,0) ;
                  sUVPnt2 = sUVDomain.Evaluate(1,0) ;
                  pUVPlane->EvaluatePointFast(sUVPnt1,  sPnt1) ;
                  pUVPlane->EvaluatePointFast(sUVPnt2,  sPnt2) ;
                  break ;
          case 3: // VMAX
                  sUVPnt1 = sUVDomain.Evaluate(0,1) ;
                  sUVPnt2 = sUVDomain.Evaluate(1,1) ;
                  pUVPlane->EvaluatePointFast(sUVPnt1,  sPnt1) ;
                  pUVPlane->EvaluatePointFast(sUVPnt2,  sPnt2) ;
                  break ;
        }

      // color code seams, singularities, and regular boundaries
      if     (bSeam[ii]) smgfx_OutputColor(.3,.7,.7, pOptGfxSet) ;
      else if(bSing[ii]) smgfx_OutputColor(.7,.0,.3, pOptGfxSet) ;
      else               smgfx_OutputColor(.5,.5,.5, pOptGfxSet) ;

      // Draw the UVPlane 3d icon boundary
      if(bDraw2dBoundaries)
        {
          smgfx_OutputLine(sPnt1.x, sPnt1.y, sPnt1.z, sPnt2.x, sPnt2.y, sPnt2.z, pOptGfxSet) ;
        }

      // add in Surface 3d Boundary Curves when asked
      if(bDraw3dBoundaries)
        {
          SmLine *pLine ;
          sPnt1.Set(sUVPnt1.x, sUVPnt1.y, 0.0) ;
          sPnt2.Set(sUVPnt2.x, sUVPnt2.y, 0.0) ;
          SmLine::CreateLineSegment(sContext, 2, sPnt1, sPnt2, pLine) ;
          SmObjDelete sCleanLine(pLine) ;
          DrawUVCurve(*pLine, FALSE, 1, FALSE, pOptGfxSet) ;
        }

    } // end render 4 sides of Surface Natural Boundary

  // end displayList
  smgfx_SetColor(sColor, pOptGfxSet) ;
  smgfx_SetLineWidth(dLineWidth, pOptGfxSet) ;
  pRtn = smgfx_Close(pOptGfxSet) ;

#else
  SM_REF8(cpOptUVCurves, cpOptUVDomain, bDraw2dBoundaries, bDraw3dBoundaries, bAddNormals, dNormalScale, cpContext, pOptGfxSet);
#endif // SM_GFX_CODE
  return(pRtn) ;

} // end SmSurface::DrawUVDomain

/*******************************************************************//**
PURPOSE:  Create a plane to use for drawing UV data on a plane near the surface

NOTES: The output object ppUVPlane has to be freed by the caller.
***********************************************************************/
void SmSurface::GetNearPlaneForUVDraw
  (SmPlane         ** ppUVPlane,       // out: UVPlane upon which UVTrimCurves can be drawn as a unitSquare icon.
                                       //      Needs to be freed by caller, NULL to ignore, default:[NULL]
   const SmExtent2d * cpOptUVDomain)   // in : Subdomain to size UVPlane Graphic size - always draw full surface
                                       //      NULL=Use NaturalUVDomain, default:[NULL]
 const
{
  // init output
  if(ppUVPlane && *ppUVPlane) { delete *ppUVPlane ; *ppUVPlane = NULL ; }

  // set up the plane memory
  SmPoint3d   sOrigin(0,0,0), sNorm(0,0,1) ;
  *ppUVPlane = new (GetContext()) SmPlane(sOrigin, sNorm) ;
  SmObjDelete sCleanPlane(*ppUVPlane) ;

  // set up the UVPlane 3d icon surface
    {
      SmExtent3d    sBBox3d ;
      SmPseudoBox   sPseudoBox ;
      SmSurface   * pCopySurface = NULL ;
      SmObjDelete   sClean(NULL) ;
      SmExtent2d    sUVDomain = this->GetNaturalUVDomain() ;
      double        dUVTol    = sUVDomain.GetMaxDimension() / 100.0 ;

      // Get sBBoxUV for sizing the UVPlane 3d icon
      SmExtent2d sBBoxUV = cpOptUVDomain ? *cpOptUVDomain : sUVDomain ;

      // adjust to optional subdomains - trim a surface copy and work with that for sizing and orienting the plane
      if(!sBBoxUV.AreEqual(sUVDomain, dUVTol)) { // copy and trim surface to given subdomain
                                                 Copy(*GetContext(), pCopySurface) ;
                                                 sClean.SetObj(pCopySurface) ;
                                                 pCopySurface->TrimWithDomain(sBBoxUV) ;
                                               }
      else                                     { // Set CopySurface to point to this
                                                 pCopySurface = (SmSurface *)this ;
                                               }

      // Get the surfaces's bounding boxes
      pCopySurface->CalculateBoundingBox(sBBoxUV, &sBBox3d, &sPseudoBox) ;

      // orient the plane for drawing UVPlane graphics to the pseudo box
      double dTmp = 0.0 ;
      ULONG  lTmp = 0;
      ULONG sIndex[3] = {0, 1, 2} ;
      SmPoint3d sSizes = sPseudoBox.GetIntervalSizes() ;

      // order the PseudoBox intervals from longest to shortest
      if(sSizes[0] < sSizes[1])
      {
        dTmp = sSizes[0]; sSizes[0] = sSizes[1]; sSizes[1] = dTmp;
        lTmp = sIndex[0]; sIndex[0] = sIndex[1]; sIndex[1] = lTmp;
      }

      if(sSizes[1] < sSizes[2])
      {
        dTmp = sSizes[1]; sSizes[1] = sSizes[2]; sSizes[2] = dTmp;
        lTmp = sIndex[1]; sIndex[1] = sIndex[2]; sIndex[2] = lTmp;
      }

      if(sSizes[0] < sSizes[1])
      {
        dTmp = sSizes[0]; sSizes[0] = sSizes[1]; sSizes[1] = dTmp;
        lTmp = sIndex[0]; sIndex[0] = sIndex[1]; sIndex[1] = lTmp;
      }

      // orient a TmpPlane with the longest two pseudo box intervals
      SmVector3d sX, sY, sZ ;
      SmVector2d sX2d, sY2d ;
      SmVector3d sTmpX = sPseudoBox.GetBasis(sIndex[0]) ;
      SmVector3d sTmpY = sPseudoBox.GetBasis(sIndex[1]) ;

      // unitize and orthogonalize sTmpX and sTmpY
      sTmpX.Unitize() ;
      sTmpY = sTmpX * sTmpY * sTmpX ;
      sTmpY.Unitize() ;

      // Pick X in the XY TmpPlane so that it lines up with Du
      SmVector3d sSrfPt, sSrfDU, sSrfDV ;
      pCopySurface->Evaluate1stDerivatives( sBBoxUV.Evaluate(0.01, 0.01), TRUE, TRUE, sSrfPt, sSrfDU, sSrfDV) ;
      SM_ASSERT(sSrfDU.Length() > SM_EFF_ZERO) ;
      SM_ASSERT(sSrfDV.Length() > SM_EFF_ZERO) ;
      SM_ASSERT((sSrfDU * sSrfDV).Length() > SM_EFF_ZERO) ;
      if(   sSrfDU.Length() < SM_EFF_ZERO
         || sSrfDV.Length() < SM_EFF_ZERO
         || (sSrfDU * sSrfDV).Length() < SM_EFF_ZERO)
        { return ; }

      smgu_VecLinCombTwoVectors(sTmpX, sTmpY, sSrfDU, sX2d) ;
      smgu_VecLinCombTwoVectors(sTmpX, sTmpY, sSrfDV, sY2d) ;
      sX = sX2d.x * sTmpX + sX2d.y * sTmpY ;
      sY = sY2d.x * sTmpX + sY2d.y * sTmpY ;

      // unitize and orthogonalize sX and sY and sZ
      sX.Unitize() ;
      sY = sX * sY * sX ;
      sY.Unitize() ;
      sZ = sX * sY ;

      // Set Scale = 1 and place all the plane size in the UVDomain
      SmVector2d sUVScale(sBBoxUV.XLength() > SM_EFF_ZERO ? sSizes[0]/sBBoxUV.XLength() : sSizes[0],
                          sBBoxUV.YLength() > SM_EFF_ZERO ? sSizes[1]/sBBoxUV.YLength() : sSizes[1]) ;

      // offset the plane origin from the min corner in the shortest interval direction
      sOrigin =   sPseudoBox.Evaluate(0,0,0)
                - sX * sUVScale.x * sBBoxUV.GetUMin()
                - sY * sUVScale.y * sBBoxUV.GetVMin()
                + sZ * smos_Max(1.0, sSizes[2]) * 1.3 ;

      // save the plane
      SmAxis2Placement sPosition( sOrigin, sX, sY ) ;
      (*ppUVPlane)->SetUVScale(sUVScale) ;
      (*ppUVPlane)->SetPosition(sPosition) ;
      (*ppUVPlane)->UpdateAnalyticalDomain(sBBoxUV) ;
      (*ppUVPlane)->MakeNurb() ;

    } // end setting up the UVPlane icon surface scope

  // all done
  sCleanPlane.Clear() ;

} // end SmSurface::GetNearPlaneForUVDraw

