/*******************************************************************//**
PURPOSE:  Draw a UVBox projected through the surface.

NOTES:
***********************************************************************/
SmDisplayList * SmSurface::DrawUVBox
 (SmExtent2d    & rBBox,         // in : TRUE = Draw Node center Points (red=OnBdry,green=in,blue=out)
  SmGfxArraySet * pOptGfxSet)    // i/o: used for OpenGL ES 2.0. When given, accumulate GfxVertexArrays not GL calls.
                                 //      NULL to ignore, default:[NULL]
 const
{
#ifdef SM_USE_GLOBAL_CACHE
  SmContext sContext( 16, 1, 1, 1 );
#else
    SmContext sContext;
#endif //SM_USE_GLOBAL_CACHE

  SmDisplayList *pRtn = NULL ;
  SmPoint2d sUVBox00(rBBox.GetUMin(), rBBox.GetVMin()) ;

  SmPoint3d sBox00(rBBox.GetUMin(), rBBox.GetVMin(), 0.0 ) ;
  SmPoint3d sBox10(rBBox.GetUMax(), rBBox.GetVMin(), 0.0 ) ;
  SmPoint3d sBox11(rBBox.GetUMax(), rBBox.GetVMax(), 0.0 ) ;
  SmPoint3d sBox01(rBBox.GetUMin(), rBBox.GetVMax(), 0.0 ) ;

  SmLine sUVLine0(sBox00, sBox10, 2, &sContext) ;
  SmLine sUVLine1(sBox10, sBox11, 2, &sContext) ;
  SmLine sUVLine2(sBox11, sBox01, 2, &sContext) ;
  SmLine sUVLine3(sBox01, sBox00, 2, &sContext) ;

  SmCrvOnSurf s3DLine0(sUVLine0, *(SmSurface*)this) ;
  SmCrvOnSurf s3DLine1(sUVLine1, *(SmSurface*)this) ;
  SmCrvOnSurf s3DLine2(sUVLine2, *(SmSurface*)this) ;
  SmCrvOnSurf s3DLine3(sUVLine3, *(SmSurface*)this) ;

  SmPoint3d sPnt ;
  EvaluatePoint(sUVBox00, sPnt) ;

#ifdef SM_GFX_CODE
  // Get global SmGraphicsExtern.cpp:s_Disp display parameters
  SmDisplayParameters sDisp ;
  smgfx_GetGlobalDisplayParameters(sDisp) ;

  // open display list (unless one is already open)
  smgfx_Open(smgfx_GetRuleColor(this, sDisp.GetShadedColorRule()), NULL, NULL, FALSE, pOptGfxSet);

  smgfx_DrawPoint(sPnt.x, sPnt.y, sPnt.z, pOptGfxSet);
  s3DLine0.Draw(NULL, FALSE, NULL, pOptGfxSet) ;
  s3DLine1.Draw(NULL, FALSE, NULL, pOptGfxSet) ;
  s3DLine2.Draw(NULL, FALSE, NULL, pOptGfxSet) ;
  s3DLine3.Draw(NULL, FALSE, NULL, pOptGfxSet) ;

  // end displayList
  pRtn = smgfx_Close(pOptGfxSet) ;

#else
  SM_REF1(pOptGfxSet);
#endif // end SM_GFX_CODE
  return(pRtn) ;

} // end SmSurface::DrawUVBox

/********************************************************************//**
PURPOSE: Output a table and visually compare a 3dCurve and it's UVTrimCurve
 projected through this surface.

NOTES:
  lOutputIndex an orof the following bits
  0 = [blue]   draw 'this' 3dCurve sample points
  1 = [red]    Add UVTrimCurve Points and normals for sample parameter values
  2 = [green]  Add Drop 3dCurve pts to UVTrimCurve Points and normals
  4 = [cyan]   Add Drop 3dCurve pts to Surface Points
  8 = [orange] Add Drop FoundSurface pts to UVTrimCurve Points and normals
 16 =          Add vectors between drawn points

  Step along 'this' curve, comparing points to both drop points and common
  parameter points on the UVTrimCurve defined as crSurface(crUVTrimCurve).
 Print the results -- parameters and distances -- and optionally display them.

USAGE NOTES ---
************************************************************************/
SmDisplayList * SmSurface::DrawInspectUVTrimCurve // eff: check gaps between curves and surface
 (const SmCurve    & crUVTrimCurve,               // in : UVTrimCurve (expected to share parameterization with this curve)
  const SmCurve    & cr3dCurve,                   // in : 3dCurve mated to the UVTrimCurve
  const SmExtent1d * pCurveIvl,                   // in : Ivl to draw, NULL=NaturalIvl, default:[NULL]
  ULONG              lSampleCnt,                  // in : Number of samples, default:[100]
  SmBoolean          bDrawUVPlane,                // in : TRUE = Display UVTrimCurves on a UVplane icon near the surface, FALSE = don't
                                                  //      default:[FALSE]
  ULONG              lOutputIndex,                // in :   0=[blue]   draw 'this' 3dCurve sample points
                                                  //      & 1=[red]    Add UVTrimCurve Points and normals for sample parameter values
                                                  //      & 2=[green]  Add Drop 3dCurve pts to UVTrimCurve Points and normals (Debug mode only)
                                                  //      & 4=[cyan]   Add Drop 3dCurve pts to Surface Points  (Debug mode only)
                                                  //      & 8=[orange] Add Drop FoundSurface pts to UVTrimCurve Points and normals
                                                  //      &16=         add vectors between drawn points
   SmGfxArraySet   * pOptGfxSet)                  // NotUsed: i/o: used for OpenGL ES 2.0. When given, accumulate GfxVertexArrays not GL calls.
                                                  //      NULL to ignore, default:[NULL]
 const
{
  SM_REF1(pOptGfxSet) ;
  // pass the call along to the Curve Draw function
  return
   ( cr3dCurve.DrawInspectUVTrimCurve( *this, crUVTrimCurve, pCurveIvl, lSampleCnt, bDrawUVPlane, lOutputIndex)) ;

} // end SmSurface::DrawInspectUVTrimCurve

/*******************************************************************//***
PURPOSE: Run over a grid of points on 'this', dropping to pSrf2.
  Then display the results in a variety of ways.

NOTES:
  Good for checking coincidence, near-tangency, etc.
  Tweak the static variables in the debugger.
  And feel free to change anything in the code.

  Then there are a bunch of graphics possibilities.
  One tests which surface point is 'on top' and colors the output appropriately.
  So you can look at two surfaces near their intersection and see
  how they behave -- where one crosses over the other, etc.

  Can also be used to check a single surface: if pSrf2 is null,
  just draws the points on pSrf1 as they're evaluated.

Graphics options: static variables that you can tweak interactively in the debugger.
These are described in more detail where they are used.

  u1Lo, u1Hi, v1Lo, v1Hi       : domain on 'this' to grid up
  lNumU, lNumV                 : grid size
  dMinGapDisplay               : Minimum length gap vector to display: below this, draw a point (midpoint).
  dMaxGapDisplay               : allows you to display only small vectors -- where the surfaces are close.
  bDrawSrf1Pt, bDrawSrf2Pt     : draw either surface point
  bDrawSrf1Norm, bDrawSrf2Norm : draw either surface normal
  dNormLength                  : scale factor for drawing normals
  sSrf1Color, sSrf2Color       : default colors for surface points; can be changed interactively.
  dSamePoint                   : for above/below, colors in different colors if below this threshold.

Potential enhancements:

  Don't drop points: allow just to eval two surfaces over predetermined sub-domains.

 *************************************************************************/
void SmSurface::DrawInspectTwoSurfaces
 (const SmSurface * pSrf2,
  SmGfxArraySet   * pOptGfxSet) // i/o: used for OpenGL ES 2.0. When given output GfxVertexArrays not GL calls.
 const                          //      NULL to ignore, default:[NULL]
{
#ifdef SM_GFX_OUTPUT_CODE

  // The parameters: tweak in the debugger:

  // Domain on 'this'.  These are normalized: 0-1.
  double u1Lo = 0.0, u1Hi = 1.0, v1Lo = 0.0, v1Hi = 1.0;

  int lNumU = 25, lNumV = 25;

  // These values currently behave like Booleans, but I'm making them ints
  // in case we want more choices sometime.
  SmBoolean bDrawSrf1Pt = FALSE;
  SmBoolean bDrawSrf2Pt = FALSE;
  const SmVector3d sSrf1Color( 0,1,1 ); // cyan
  const SmVector3d sSrf2Color( 0,1,0 ); // green

  SmBoolean bDrawSrf1Norm = FALSE;
  SmBoolean bDrawSrf2Norm = FALSE;

  double dNormLength = 0.1;

  double dMaxGapDisplay = 0.01;

  double dSamePoint = SM_EFF_ZERO;

  // Minimum length gap vector to display: below this, draw a point (midpoint).
  // If you want to always draw the point, make this large.
  // If negative, draw both (vector and midpoint).
  // If exactly zero, draw neither.
  double dMinGapDisplay = 0.001;

  int bEvalGeometric = 0;  // Evaluate the following geometric quantaties.

  double dGaussK1, dNormK1, dPrinK11, dPrinK21;
  SmVector3d sEFG1, sLMN1, sPrinVec11, sPrinVec21;
  double dGaussK2, dNormK2, dPrinK12, dPrinK22;
  SmVector3d sEFG2, sLMN2, sPrinVec12, sPrinVec22;

  // Just a local to store the max distance, if you're interested.
  double dMaxDistFound = 0;

  // Locals
  SmExtent2d sDom1 = this->GetNaturalUVDomain();
  SmExtent2d sDom2;
  if ( pSrf2 ) { sDom2 = pSrf2->GetNaturalUVDomain(); }

  SmPoint2d sUV1, sUV2;
  SmPoint3d sPt1, sPt2;

  SmPoint2d *pGuessUVPtr = NULL;

  SmPoint3d sMidPt;
  SmVector3d sGap, sNorm1, sNorm2;
  double dGapDist;
  SmBoolean bSuccess;
  SmBoolean bIsMulti;

  int ii, jj;

  if ( FALSE )
    { smgfx_Erase(); }
  smgfx_SetLook( 1,2, 0,1,1, pOptGfxSet); this->Draw(FALSE, pOptGfxSet); sm_GraphicsLoop();
  smgfx_SetLook( 1,2, 1,0,1, pOptGfxSet); if ( pSrf2 ) pSrf2->Draw(FALSE, pOptGfxSet); sm_GraphicsLoop();
  sm_GraphicsLoop();


  for ( ii = 0; ii <= lNumU; ii++ )
  {
    sm_GraphicsLoop(); // can be handy...  Breakpoint here.

    double uFrac = (double)ii / (double)lNumU;
    double uNorm = (1-uFrac) * u1Lo + uFrac * u1Hi;

    for ( jj = 0; jj <= lNumV; jj++ )
    {
      double vFrac = (double)jj / (double)lNumV;
      double vNorm = (1-vFrac) * v1Lo + vFrac * v1Hi;

      sUV1 = sDom1.Evaluate( uNorm, vNorm );
      this->EvaluatePoint( sUV1, sPt1 );

      if ( pSrf2 == NULL )
      {
          // Just looking at pSrf1.
          smgfx_SetLook( 2,4, sSrf1Color.x, sSrf1Color.y, sSrf1Color.z, pOptGfxSet ); sPt1.Draw(NULL, NULL, pOptGfxSet); sm_GraphicsLoop();
          continue;
      }

      pSrf2->DropPoint( sPt1, sDom2, pGuessUVPtr,
                        bSuccess, sUV2, dGapDist, bIsMulti );

      if ( !bSuccess )
        { continue; } // breakpoint

      pGuessUVPtr = &sUV2; // for after the first time.

      if ( dGapDist > dMaxDistFound )
        { dMaxDistFound = dGapDist; }

      // Limit on how big a gap to display.
      // Can be handy for surface intersections: large gaps that are not
      // near the intersection can muddle up the display.
      // To display all, make it a big number (e.g. 100).

      if ( dGapDist > dMaxGapDisplay )
        { continue; }

      pSrf2->EvaluatePoint( sUV2, sPt2 );

      // Do the graphics.
      if(bDrawSrf1Pt)
      {
        smgfx_SetLook( 2,4, sSrf1Color.x, sSrf1Color.y, sSrf1Color.z, pOptGfxSet ); sPt1.Draw(NULL, NULL, pOptGfxSet); sm_GraphicsLoop();
      }
      if(bDrawSrf2Pt)
      {
        smgfx_SetLook( 2,4, sSrf2Color.x, sSrf2Color.y, sSrf2Color.z, pOptGfxSet ); sPt2.Draw(NULL, NULL, pOptGfxSet); sm_GraphicsLoop();
      }
      sm_GraphicsLoop();

      if(bDrawSrf1Norm)
      {
        this->EvaluateNormal( sUV1, FALSE, FALSE, sNorm1 );
        sNorm1 *= dNormLength;
        smgfx_SetLook( 2,4, sSrf1Color.x, sSrf1Color.y, sSrf1Color.z, pOptGfxSet ); sNorm1.Draw( &sPt1, NULL, pOptGfxSet ); sm_GraphicsLoop();
      }
      // We're going to need this below anyway:
      pSrf2->EvaluateNormal( sUV2, FALSE, FALSE, sNorm2 );
      if(bDrawSrf2Norm)
      {
        sNorm2 *= dNormLength;
        smgfx_SetLook( 2,4, sSrf2Color.x, sSrf2Color.y, sSrf2Color.z, pOptGfxSet ); sNorm2.Draw( &sPt2, NULL, pOptGfxSet ); sm_GraphicsLoop();
      }
      sm_GraphicsLoop();

      sGap = sPt2 - sPt1;
      sMidPt = 0.5 * ( sPt1 + sPt2 );

      sPt1 = sMidPt - sGap / 2;;

      // Check whether sPt2 is 'above' or 'below' sPt1.
      // Dot w/ srf2 norm, because we dropped to srf2, so that's supposed to be parallel.

      double dDot = sGap.Dot( sNorm2 );

      if ( smos_Fabs( dDot ) < dSamePoint )
        { smgfx_SetLook( 4,6, 1,0,0 ); }
      else if ( dDot > 0 )
        { smgfx_SetLook( 2,4, 0,1,0 ); }
      else
        { smgfx_SetLook( 2,4, 0,0,1 ); }


      if ( dMinGapDisplay < 0.0 )  // If set negative, draw both.
      {
        sGap.Draw( &sPt1, NULL, pOptGfxSet); sm_GraphicsLoop();
        sMidPt.Draw(NULL, NULL, pOptGfxSet);      sm_GraphicsLoop();
      }
      else if ( dMinGapDisplay == 0 )  // Zero, draw neither
        {}
      else if ( sGap.Length() > dMinGapDisplay )
      {
        sGap.Draw( &sPt1, NULL, pOptGfxSet ); sm_GraphicsLoop();  // Long enough, draw gap vector.
      }
      else
      {
        sMidPt.Draw(NULL, NULL, pOptGfxSet); sm_GraphicsLoop();  // Too short, just draw midpoint.
      }

      if ( bEvalGeometric > 0 )
      {
          this->EvaluateGeometric( sUV1, FALSE, FALSE,
                      dGaussK1, dNormK1, dPrinK11, dPrinK21,
                      sEFG1, sLMN1, sPrinVec11, sPrinVec21 );

          pSrf2->EvaluateGeometric( sUV2, FALSE, FALSE,
                      dGaussK2, dNormK2, dPrinK12, dPrinK22,
                      sEFG2, sLMN2, sPrinVec12, sPrinVec22 );

      }

      sm_GraphicsLoop();

    }
  }

  sm_GraphicsLoop();
#else
  SM_REF2(pSrf2, pOptGfxSet);
#endif // SM_GFX_OUTPUT_CODE

} // end SmSurface::DrawInspectTwoSurfaces

/*******************************************************************//***
PURPOSE: Step along a curve dropping points to 'this' surface.
   Print the results -- parameters and distances -- and optionally display them.

NOTES:
   Useful for inspecting closely the behavior of a curve and a surface,
   especially when they're very close, nearly tangent, etc., down below
   the level of the graphical user interface.

   You can tweak the parameters -- dStartParam, dEndParam, and
   iNumTries -- interactively as you proceed, to "zoom in".

  And feel free to change anything in the code.
************************************************************************/
void SmSurface::DrawInspectCurveSurface
 (const SmCurve * pCrv,
  SmGfxArraySet * pOptGfxSet) // i/o: used for OpenGL ES 2.0. When given output GfxVertexArrays not GL calls.
                             //      NULL to ignore, default:[NULL]
 const
{
  SmExtent1d sCrvDomain = pCrv->GetNaturalInterval();
  SmExtent2d sSrfDomain = this->GetNaturalUVDomain();

  double dStartParam = sCrvDomain.GetMin();
  double dEndParam   = sCrvDomain.GetMax();
  constexpr int    iNumTries = 25;

  SmPoint3d sCrvPt, sSrfPt;
  SmVector3d sGap, sNorm;
  double dT1, dDist;
  SmPoint2d sGuessUV, sDropUV;
  SmPoint2d *pGuessPtr = NULL; // no guess for first drop (use global).
  SmBoolean bSuccess;
  SmBoolean bIsMulti;
  int ii;
  TCHAR sBuff[SM_TBLOCK_SIZE];

  for ( ii = 0; ii <= iNumTries; ii++ )
    {
      dT1 = ((double)ii) / (double)(iNumTries);
      dT1 = dStartParam + dT1 * ( dEndParam - dStartParam );
      pCrv->EvaluatePoint( dT1, sCrvPt );

      this->DropPoint( sCrvPt, sSrfDomain, pGuessPtr, bSuccess, sDropUV, dDist, bIsMulti );

      if ( bSuccess )
        {
          smos_sprintf(sBuff, _T("\n crv t %16.16lf   uv %16.16lf %16.16lf   dist %16.16lf"),
              dT1, sDropUV.x, sDropUV.y, dDist );

          sGuessUV = sDropUV;
          pGuessPtr = & sGuessUV; // guess param for subsequent drops.
        }
      else
        {
          smos_sprintf(sBuff,_T("%s"), _T("\n   ...  Drop failed."));
          continue;
        }
      smos_WriteBuffer(sBuff);

#ifdef SM_DEBUG_CODE
      static int iDebug = 0;

      if ( iDebug == 1 ) // 1: draw surface normals
        {
          smgfx_SetLook( 2,3, 0,1,0 , pOptGfxSet); this->DrawAt( sDropUV, 1, pOptGfxSet); sm_GraphicsLoop();
          sm_GraphicsLoop();
        }

      if ( iDebug <= 2 )
        {
          this->EvaluatePoint( sDropUV, sSrfPt );
          sGap = sSrfPt - sCrvPt;
          this->EvaluateNormal( sDropUV, FALSE, FALSE, sNorm  );
          double dDot = sGap.Dot( sNorm );
          if ( dDot < 0 )
            { smgfx_SetLook( 3,5, 0,0,1 ); }
          else
            { smgfx_SetLook( 3,5, 0,1,0 ); }
          sCrvPt.DrawPointToPoint( sSrfPt, NULL, pOptGfxSet ); sm_GraphicsLoop();
          sm_GraphicsLoop();
        }
#else
      SM_REF1(pOptGfxSet);
#endif // SM_DEBUG_CODE
    }

  smos_sprintf(sBuff, _T("%s"),_T("\n"));
  smos_WriteBuffer(sBuff);

} // end DrawInspectCurveSurface

/*******************************************************************//***
PURPOSE: Step along a uv curve evaluating points and normals.
   Print the results and optionally display them.

NOTES:
   Useful for inspecting closely the behavior of a surface along a uv curve.

   You can tweak the parameters -- dStartParam, dEndParam, and
   iNumTries -- interactively as you proceed, to "zoom in".

  And feel free to change anything in the code.
************************************************************************/
void SmSurface::DrawInspectSurfaceCurve
 (const SmCurve * pCrv,       // in : 
  SmGfxArraySet * pOptGfxSet) // NotUsed: i/o: used for OpenGL ES 2.0. When given output GfxVertexArrays not GL calls.
                              //      NULL to ignore, default:[NULL]
 const
{
  SM_REF1(pOptGfxSet) ;
  SmExtent1d sCrvDomain = pCrv->GetNaturalInterval();
  SmExtent2d sSrfDomain = this->GetNaturalUVDomain();

  double dStartParam = sCrvDomain.GetMin();
  double dEndParam   = sCrvDomain.GetMax();
  int    iNumTries = 25;
  int    iDebugDump = 0;

#ifdef SM_DEBUG_CODE
  static int iDebugDraw = 0;

  if ( FALSE )
    { smgfx_Erase(); }
  smgfx_SetLook( 1,2, 0,0,1 ); this->DrawUV( 3, 3 ); sm_GraphicsLoop();
  sm_GraphicsLoop();
#endif // SM_DEBUG_CODE

  SmPoint2d  sUV2d;
  SmPoint3d  sUV3d, sSrfPt;
  SmVector3d sSu, sSv, sNorm;
  SmVector3d sEvalMat[4][4];
  double dT1;
  int ii;
  TCHAR sBuff[SM_TBLOCK_SIZE];

  for ( ii = 0; ii <= iNumTries; ii++ )
    {
      dT1 = ((double)ii) / (double)(iNumTries);
      dT1 = dStartParam + dT1 * ( dEndParam - dStartParam );
      pCrv->EvaluatePoint( dT1, sUV3d );

      sUV2d.Set( sUV3d.x, sUV3d.y );
      this->EvaluatePoint ( sUV2d, sSrfPt );

      if ( iDebugDump > 0 )
      {
          smos_sprintf(sBuff, _T("\n crv t %16.16lf   uv %16.16lf %16.16lf"),
              dT1, sUV2d.x, sUV2d.y );
          smos_WriteBuffer(sBuff);
      }

      if ( iDebugDump > 1 )
      {
          this->EvaluateNormal( sUV2d, FALSE, FALSE, sNorm  );
          smos_sprintf(sBuff, _T("\n   pt %16.16lf %16.16lf %16.16lf  norm %16.16lf %16.16lf %16.16lf"),
                     sSrfPt.x, sSrfPt.y, sSrfPt.z, sNorm.x, sNorm.y, sNorm.z );
          smos_WriteBuffer(sBuff);
      }

      if ( iDebugDump > 2 )
      {
          this->Evaluate1stDerivatives( sUV2d, FALSE, FALSE, sSrfPt, sSu, sSv );
          smos_sprintf(sBuff, _T("\n   d/du %16.16lf %16.16lf %16.16lf  d/dv %16.16lf %16.16lf %16.16lf"),
              sSu.x, sSu.y, sSu.z, sSv.x, sSv.y, sSv.z );
          smos_WriteBuffer(sBuff);
      }

      if ( FALSE )
      {
          // set in debugger:
          ULONG lNumDeriv = 3;
          SmBoolean bUFromLeft = FALSE;
          SmBoolean bVFromLeft = FALSE;
          SmBoolean bOnlyUpperHalf = TRUE;

          this->Evaluate( sUV2d, lNumDeriv, lNumDeriv,
                          bUFromLeft, bVFromLeft, bOnlyUpperHalf,
                          sEvalMat[0] );

          sSu = sEvalMat[1][0];
      }

#ifdef SM_DEBUG_CODE
      if ( iDebugDraw > 0 ) // draw surface normals
        {
          smgfx_SetLook( 2,3, 0,1,0 ); this->DrawAt( sUV2d, 1 ); sm_GraphicsLoop();
          sm_GraphicsLoop();
        }
#endif // SM_DEBUG_CODE
    }

  smos_sprintf(sBuff, _T("%s"),_T("\n"));
  smos_WriteBuffer(sBuff);

} // end DrawInspectSurfaceCurve

/*******************************************************************//**
PURPOSE: Write Surface to file

NOTES:
***********************************************************************/
SmStatus SmSurface::WriteToFile
  (const TCHAR * cOutputFileName,      // in : target file name
   SmBoolean     bSkipHeaderWrite,     // NotUsed: in : TRUE = Omit "Surface Type: TYPE" header label
   SmBoolean     bNewFile,             // in : TRUE = open file and rewrite contents      
                                       //      FALSE= open file and append to end
   SmBoolean     bWriteAttributes)     // in : TRUE=Write attributes, FALSE=don't
  const
{
  SM_REF1(bSkipHeaderWrite) ;
  SM_ASSERT_VALID_NO_STREAM(this) ;
  TCHAR            sBuff[SM_TBLOCK_SIZE] ;
  SmDatabaseIOFile sDB ;
  long             lDBVersionNumber = SM_CURRENT_DATABASE_VERSION ;

  // open file for output
  if(SM_SUCCESS != sDB.OpenFileForWrite(cOutputFileName, // in : target file name
                                        SM_ASCII,        // in : oneof: SM_ASCII    = write ascii file with comment lines
                                                         //             SM_BINARY   = write binary file from system format to LittleEndian
                                                         //             SM_BYTESWAP = write binary file - forcing byte swap
                                                         //      default:[SM_ASCII]
                                        bNewFile))       // in : bNewFile = TRUE  = open file and rewrite contents
                                                         //                 FALSE = open file and append to end
                                                         //                 default:[FALSE]
    {
      smos_sprintf(sBuff,_T("  *** ERROR File not found - %s\n"),cOutputFileName);
      smos_WriteBuffer(sBuff);
      return SM_ERR;
    }
  // std::ostream & rFileOut = *sDB.GetOutStreamPtr();

  // Output header string - no longer optional
  SM_TYPE lType = GetType() ;
  sDB.WriteType(lType) ;   //  SM_CURRENT_DATABASE_VERSION > 32   << "Object Type " << lType << "\n"

  // pass the call along to appropriate derived type
  WriteToDB(sDB, lDBVersionNumber) ;

  // handle attributes
  if(bWriteAttributes && lDBVersionNumber > 30)
    {
       const SmContext *cpContext = GetContext() ;

       if(cpContext != NULL)
         {
           SmTArray<ULONG>                     sThisAttributes ;
           SmTArray<SmAttribute*>              sAllAttributes ;
           SmMapTypeToType<SmAttribute*,ULONG> sAttrMap ; 
           SER(sm_ExtractAttributes(*cpContext,this,sThisAttributes,sAllAttributes,sAttrMap));
           SmAttributeData::WriteIndexedAttributesToDB(sThisAttributes,sDB);
           // if (pAttributes) { delete pAttributes ; pAttributes = NULL ; }
         } // end surface has context check
    } // end write attribute check

  // all done
  return SM_SUCCESS;

} // end SmSurface::WriteToFile

/*******************************************************************//**
PURPOSE: Write Array Of Surfaces to File

NOTES:
***********************************************************************/
SmStatus SmSurface::WriteArrayToFile
  (const TCHAR                 * cOutputFileName,  // in : target file name
   const SmTArray<SmSurface *> & rSrfArr,          // in : array of surfaces to write
   SmBoolean                     bWriteAttributes) // in : TRUE=Write attributes, FALSE=don't
{
  SmDatabaseIOFile sDB ;
  TCHAR            sBuff[SM_TBLOCK_SIZE] ; 
  long             lDBVersionNumber = SM_CURRENT_DATABASE_VERSION ;

  // check input
  ULONG lSrfCnt = rSrfArr.GetSize();
  if (lSrfCnt < 1)
    { return  SM_ERR ; }

  // open file for output
  if(SM_SUCCESS != sDB.OpenFileForWrite(cOutputFileName, // in : target file name
                                        SM_ASCII,        // in : oneof: SM_ASCII    = write ascii file with comment lines
                                                         //             SM_BINARY   = write binary file from system format to LittleEndian
                                                         //             SM_BYTESWAP = write binary file - forcing byte swap
                                                         //      default:[SM_ASCII]
                                        TRUE))           // in : bNewFile = TRUE  = open file and rewrite contents
                                                         //                 FALSE = open file and append to end
                                                         //                 default:[FALSE]
    {
      smos_sprintf(sBuff,_T("  *** ERROR File not found - %s\n"),cOutputFileName);
      smos_WriteBuffer(sBuff);
      return SM_ERR;
    }
  std::ostream & rFileOut = *sDB.GetOutStreamPtr();

  // output max index number
  lSrfCnt--;
  rFileOut << lSrfCnt << "\n" ;

  // output the surfaces
  ULONG ii ;
  for(ii=0;ii<=lSrfCnt;ii++)
   {
      SmSurface *pSrf  = rSrfArr[ii];
      SM_ASSERT_VALID_NO_STREAM( pSrf );

      // write surface type and dim
      SM_TYPE  lType = pSrf->GetType() ;
      SER(sDB.WriteType(lType)) ;   //  SM_CURRENT_DATABASE_VERSION > 32   << "Object Type " << lType << "\n"

      // write surface
      SM_ASSERT_VALID_NO_STREAM(pSrf) ;
      SER(pSrf->WriteToDB(sDB, lDBVersionNumber)) ;

      // handle attributes
      if(bWriteAttributes && lDBVersionNumber > 30)
        {
           const SmContext *cpContext = pSrf->GetContext() ;

           if(cpContext != NULL)
             {
               SmTArray<ULONG>                     sThisAttributes ;
               SmTArray<SmAttribute*>              sAllAttributes ;
               SmMapTypeToType<SmAttribute*,ULONG> sAttrMap ; 
               SER(sm_ExtractAttributes(*cpContext,pSrf,sThisAttributes,sAllAttributes,sAttrMap));
               SmAttributeData::WriteIndexedAttributesToDB(sThisAttributes,sDB);
               // if (pAttributes) { delete pAttributes ; pAttributes = NULL ; }
             } // end surface has context check
        }
   } // end iter writing every surface

  // all done
  return SM_SUCCESS;

} // end SmSurface::WriteToFile  (surfaces array)

/*******************************************************************//**
PURPOSE: Read a Surface in from file.

NOTES: This method is primarily for debugging.
***********************************************************************/
SmStatus SmSurface::ReadFromFile
  (const SmContext & crContext,          // in : context for new object construction
   const TCHAR     * cInputFileName,     // in : target file
   SmSurface      *& rpNewSurface,       // out: the read surface with newly allocated memory
   const ULONG       lFileOffsetInBytes) // NotUsed: in : Number of characters in file to skip before reading)       
{
  SM_REF1(lFileOffsetInBytes) ;
  SmDatabaseIOFile sDB;
  TCHAR            sBuff[SM_TBLOCK_SIZE] ;
  SM_TYPE          lType ;

  // build and init the stream structure
  if(SM_SUCCESS != sDB.OpenFileForRead(cInputFileName, SM_ASCII))
    {
      smos_sprintf(sBuff,_T("  *** ERROR File not found - %s\n"),cInputFileName);
      smos_WriteBuffer(sBuff);
      return SM_ERR;
    }
  std::istream & rFileIn = *sDB.GetInStreamPtr();

  // backwards compatibility hack - figure out version number for file
  //  SM_CURRENT_DATABASE_VERSION <= 32  No header, or 1st word "Surface"
  //  SM_CURRENT_DATABASE_VERSION > 32   "Object"
  char c1stChar = (char)rFileIn.get() ;
  if ( c1stChar == 10 )             // line feed
       c1stChar = (char)rFileIn.get() ;
  rFileIn.unget();  // peek was not working in VS10
  ULONG lDBVersionNumber = (c1stChar == 'O') ? SM_CURRENT_DATABASE_VERSION : 30 ;

  // branch on version number
  if(lDBVersionNumber > 32)
    {
      sDB.ReadType(lType) ;
    }
  else // old style write
    {
      lType = SmBSplineSurface_TYPE ;
      if(c1stChar == 'S')
        { sDB.GoToNextLine() ; }
    } // end branch for SM_CURRENT_DATABASE_VERSION <= 32

  // pass the call along to appropriate derived type
  SmSurface::ReadFromDB(lType, sDB, crContext, rpNewSurface, lDBVersionNumber) ;

  // all done
  return SM_SUCCESS;

} // end SmSurface::ReadFromFile - for single surface

/*******************************************************************//**
PURPOSE: Read an Array of Surfaces in from a file.

NOTES: This method is primarily for use when debugging.
***********************************************************************/
SmStatus SmSurface::ReadArrayFromFile
  (const SmContext        & crContext,          // in : context for new object construction
   const TCHAR            * cInputFileName,     // in : target file
   SmTArray <SmSurface *> & rNewSurfaces,       // out: the read surface with newly allocated memory
   const ULONG              lFileOffsetInBytes, // NotUsed: in : Number of characters in file to skip before reading)       
   SmTArray <SmSurface *> * pTestSurfaces)      // in : for debug only - the array of curves expected to be read  NULL to ignore, Default:[NULL]
{
  SM_REF1(lFileOffsetInBytes) ;
  SmDatabaseIOFile sDB;
  TCHAR        sBuff[SM_TBLOCK_SIZE] ;
  SM_TYPE      lType ;
  ULONG        lSrfCnt ;
  ULONG        lDBVersionNumber = 0 ;
  SmSurface  * pNewSurface = NULL ;

  // init output
  rNewSurfaces.ReSet() ;

  // build and init the stream structure
  if(SM_SUCCESS != sDB.OpenFileForRead(cInputFileName, SM_ASCII))
    {
      smos_sprintf(sBuff,_T("  *** ERROR File not found - %s\n"),cInputFileName);
      smos_WriteBuffer(sBuff);
      return SM_ERR;
    }
  std::istream & rFileIn = *sDB.GetInStreamPtr();

  // read max index number
  rFileIn >> lSrfCnt ;

  // input the surfaces
  ULONG ii ;
  for(ii=0;ii<=lSrfCnt;ii++)
    {
      // for 1st surface read
      if(lDBVersionNumber == 0)
        {
          // backwards compatibility hack - figure out version number for file
          //  SM_CURRENT_DATABASE_VERSION <= 32  No header, or 1st word "Surface"
          //  SM_CURRENT_DATABASE_VERSION > 32   "Object"
          char c1stChar = (char)rFileIn.get() ;
          if ( c1stChar == 10 )             // line feed
               c1stChar = (char)rFileIn.get() ;
          rFileIn.unget();  // peek was not working in VS10
          lDBVersionNumber = (c1stChar == 'O') ? SM_CURRENT_DATABASE_VERSION : 30 ;
        }

      // branch on version number
      if(lDBVersionNumber > 32)
        {
          sDB.ReadType(lType) ;
        }
      else // old style write
        {
          lType = SmBSplineSurface_TYPE ;
        }

      // pass the call along to appropriate derived type
      SmSurface::ReadFromDB(lType, sDB, crContext, pNewSurface, lDBVersionNumber) ;

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
      if(bDebugMe)
        {
          SM_DUMP_AND_ASSERT_VALID(pNewSurface) ;

          if(pTestSurfaces && ii < pTestSurfaces->GetSize())
            {
              // compare the just read curve with the test curve
              SM_ASSERT_MSG( *pTestSurfaces->GetAt(ii) == *pNewSurface,
                            _T("SmSurface::ReadFromFile - read surface is not the same as given comparison test surface.") ) ;
            }
        }
#else
      SM_REF1(pTestSurfaces);
#endif // SM_DEBUG_CODE

      // add surface to output
      rNewSurfaces.Add(pNewSurface) ;
      pNewSurface = NULL ;

    } // end iter to read every Surface

  // all done
  return SM_SUCCESS;

} // end SmSurface::ReadArrayFromFile - for arrays

/*******************************************************************//**
PURPOSE: To act like a virtual static method for reading any surface type.

NOTES: branches on lType and passes the read call along to the appropriate
       type surface.
***********************************************************************/
SmStatus SmSurface::ReadFromDB
 (SM_TYPE           lType,              // in : surface type to be read
  SmDatabaseIO    & rDB,                // in : target output stream
  const SmContext & crContext,          // in : context for new object construction
  SmSurface      *& rpNewSurface,       // out:    NULL on input = new object allocated in this routine built from stream data
                                        //      NotNULL on input = pointer to an empty object to be filled by this routine
  ULONG             lDBVersionNumber)   // in : database version to get proper sequence of writes
{
  // pass the call along to the appropriate derived type
  switch(lType)
    {
      case SmBSplineSurface_TYPE      : { return( SmBSplineSurface::      ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmPlane_TYPE               : { return( SmPlane::               ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmSurfOfExtrusion_TYPE     : { return( SmSurfOfExtrusion::     ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmSurfOfRevolution_TYPE    : { return( SmSurfOfRevolution::    ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmCone_TYPE                : { return( SmCone::                ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmCylinder_TYPE            : { return( SmCylinder::            ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmSphere_TYPE              : { return( SmSphere::              ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmTorus_TYPE               : { return( SmTorus::               ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmCurveBoundedSurface_TYPE : { return( SmCurveBoundedSurface:: ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmOffsetSurface_TYPE       : { return( SmOffsetSurface::       ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmSrfInVolume_TYPE         : { return( SmSrfInVolume::         ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      case SmSTEPSurface_TYPE         : { return( SmSTEPSurface::         ReadFromDB(lType, rDB, crContext, rpNewSurface, lDBVersionNumber) ) ; }
      default : SE(SM_ERR) ; return (SM_ERR) ; break ;
    } // end switch on type

} // end SmSurface::ReadFromDB

