/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmSurface::Dump
  (SmBoolean )    // in : bAbbrev
 const
{
  TCHAR sBuff[8*SM_TBLOCK_SIZE], sBuffForFile[8*SM_TBLOCK_SIZE];
  smos_WriteBuffer(_T("\nBegin SmSurface::Dump()")) ;
  smos_sprintf(sBuff,_T("\nSurface = 0x%p "),this);

  // get SurfaceCache state
  SmSurfaceCache * pSurfaceCache = (SmSurfaceCache *)SmCacheMgr::GetObjectCache(SM_OC_SURFACE, this) ;
  SmTrimSrfCache * pTrimSrfCache = (SmTrimSrfCache *)SmCacheMgr::GetObjectCache(SM_OC_TRIMSRF, this) ;
  ULONG lSurfaceCacheMemoryAllocated = 0 ;
  //ULONG lSurfaceCacheMemoryUsed = pSurfaceCache ? pSurfaceCache->GetMemoryUsed(lSurfaceCacheMemoryAllocated) : 0 ;
  ULONG lTrimSrfCacheMemoryAllocated = 0 ;
  //ULONG lTrimSrfCacheMemoryUsed = pTrimSrfCache ? pTrimSrfCache->GetMemoryUsed(lTrimSrfCacheMemoryAllocated) : 0 ;

  // get derived surface type string
  TCHAR sDerivedName[SM_TBLOCK_SIZE] ;
  switch(GetType())
    { case SmSurface_TYPE             : smos_sprintf(sDerivedName,_T("%s"),_T(" ")) ; break ;
      case SmBSplineSurface_TYPE      : smos_sprintf(sDerivedName,_T("%s"),_T("[SmBSplineSurface_TYPE]")) ;      break ;
      case SmPlane_TYPE               : smos_sprintf(sDerivedName,_T("%s"),_T("[SmPlane_TYPE]")) ;               break ;
      case SmSurfOfExtrusion_TYPE     : smos_sprintf(sDerivedName,_T("%s"),_T("[SmSurfOfExtrusion_TYPE]")) ;     break ;
      case SmSurfOfRevolution_TYPE    : smos_sprintf(sDerivedName,_T("%s"),_T("[SmSurfOfRevolution_TYPE]")) ;    break ;
      case SmCone_TYPE                : smos_sprintf(sDerivedName,_T("%s"),_T("[SmCone_TYPE]")) ;                break ;
      case SmCylinder_TYPE            : smos_sprintf(sDerivedName,_T("%s"),_T("[SmCylinder_TYPE]")) ;            break ;
      case SmSphere_TYPE              : smos_sprintf(sDerivedName,_T("%s"),_T("[SmSphere_TYPE]")) ;              break ;
      case SmTorus_TYPE               : smos_sprintf(sDerivedName,_T("%s"),_T("[SmTorus_TYPE]")) ;               break ;
      case SmCurveBoundedSurface_TYPE : smos_sprintf(sDerivedName,_T("%s"),_T("[SmCurveBoundedSurface_TYPE]")) ; break ;
      case SmOffsetSurface_TYPE       : smos_sprintf(sDerivedName,_T("%s"),_T("[SmOffsetSurface_TYPE]")) ;       break ;
      case SmSTEPSurface_TYPE         : smos_sprintf(sDerivedName,_T("%s"),_T("[SmSTEPSurface_TYPE]")) ;         break ;
      case SmSrfInVolume_TYPE         : smos_sprintf(sDerivedName,_T("%s"),_T("[SmSrfInVolume_TYPE]")) ;         break ;
      default : smos_sprintf(sDerivedName,_T("%s"),_T("[UnKnown Derived Type]")) ; break ;
    }
  smos_snprintf(sBuff, 8*SM_TBLOCK_SIZE, 
             _T("\nSmSurface%.1024s 0x%p, Owner = 0x%p[%.1024s], [pSurfaceCache = 0x%p (%ld bytes)] [pTrimSrfCache = 0x%p (%ld bytes)]"),
             sDerivedName,
             this,
             m_pOwner, m_pOwner ? m_pOwner->GetTypeString() : _T("NULL"),
             pSurfaceCache, lSurfaceCacheMemoryAllocated,
             pTrimSrfCache, lTrimSrfCacheMemoryAllocated);
  smos_snprintf(sBuffForFile, 8*SM_TBLOCK_SIZE,
             _T("\nSmSurface%s = %.1024s, Owner = %.1024s[%.1024s], [pSurfaceCache = %.1024s (%ld bytes)] [pTrimSrfCache = %.1024s (%ld bytes)]"),
             sDerivedName,
             _T("NotNULL"),
             m_pOwner      ? _T("NotNULL") : _T("NULL"),
             m_pOwner      ? m_pOwner->GetTypeString() : _T("NULL"),
             pSurfaceCache ? _T("NotNULL") : _T("NULL"), lSurfaceCacheMemoryAllocated,
             pTrimSrfCache ? _T("NotNULL") : _T("NULL"), lTrimSrfCacheMemoryAllocated);
  smos_WriteBuffer(sBuff, sBuffForFile);

  smos_WriteBuffer(_T("\n End SmSurface::Dump()\n")) ;

} // end SmSurface::Dump

/*******************************************************************//**
PURPOSE: AssertValid() Test reporting static labels
***********************************************************************/
SmAssertReportLabel sAssertSurface_list[] =
{
// Remove Composite
//  /*  0 */ {SM_AT_TYPE,        _T("Bad Surf Owner"),                _T("Surface->Owner not oneof: NULL, Face, CompositeFace, or Geometry with a GenSurface") },
  /*  0 */ {SM_AT_TYPE,        _T("Bad Surf Owner"),                _T("Surface->Owner not oneof: NULL, Face, or Geometry with a GenSurface") },
  /*  1 */ {SM_AT_GEOMETRIC,   _T("Bad Surf FlatCorner"),           _T("Surface Su and Sv Tangents in at least one corner are parallel") },
  /*  2 */ {SM_AT_GEOMETRIC,   _T("Bad Surf Degenerated to Point"), _T("Surface has degenerated into a single point") },
  /*  3 */ {SM_AT_GEOMETRIC,   _T("Bad Surf Degenerates to Curve"), _T("Surface has degenerated into a single curve") },
  /*  4 */ {SM_AT_GEOMETRIC,   _T("Bad Surf Discontinuity"),        _T("Surface sampled IsoLine contains a G1 or C0 discontinuity across a Knot Value") },
  /*  5 */ {SM_AT_GEOMETRIC,   _T("Bad Surf Pole Approximation"),   _T("Surface is close to singular at boundary - should be tightened to exactly singular") },
  /*  6 */ {SM_AT_COINCIDENCE, _T("Bad Surf Coincidence at Seam"),  _T("Open surface has partially coincident boundaries") }
} ;

/*******************************************************************//**
AssertRule Predicate names and return values:
  predicate = SmBoolean sm_AssertTestClassNameRule#() ; Rtn: TRUE=OK,    FALSE=Bad,
***********************************************************************/
/*******************************************************************//**
PURPOSE  : SmSurface AssertRule 1 - Surface Su and Sv Tangents must be independent in all 4 natural corners

  predicate = Are the angles between Su and Sv Tangents all greater than SM_ANG_TOL_DEG
  action    = If the Surface has a Face, replace the Face->Surface with
              an approximation of the current face rebuilt without dependent natural corners.
***********************************************************************/
SmBoolean sm_AssertTestSurface1        // TRUE = okay, FALSE = problem
 (const SmSurface * pSurface,          // in : target Surface
  SmTol3d         * pOptOutTol3d=NULL, // out: optional tolerance for failed assert reports
  double          * pOptOutVal=NULL)   // out: optional value for failed assert reports
{
  SmBoolean bRtn = !pSurface->HasFlatCorners(SM_ANG_TOL_DEG) ;

  // set output
  if(pOptOutTol3d) { *pOptOutTol3d = SM_ANG_TOL_DEG ; }
  if(pOptOutVal)   { *pOptOutVal   = SM_UNDEF_DOUBLE ; }
  return( bRtn ) ;

} // end sm_AssertTestSurface1

