/*******************************************************************//**
PURPOSE  : AssertRule 4 - Surfaces can't have a Interior G1 Discontinuity

  predicate = are any discontinuities across knot multiplicities of degree G1 discontinuous
  action    = reduce surface Knot multiplicity to enforce C1 continuity
***********************************************************************/
SmBoolean sm_AssertTestSurface4(const SmSurface *pSurface) // TRUE = okay, FALSE = problem
{
  /*  4 */ // Surface should not contain a G1 or C0 discontinuity
  SmContinuityType eContU, eContV;
  SmTArray<SmContinuityType> eContsU, eContsV;

  // Surface continuities across U and V knots
  pSurface->CalculateContinuities ( SM_SP_U, eContU, eContsU );
  pSurface->CalculateContinuities ( SM_SP_V, eContV, eContsV );

  // Good Surfaces have at least G1 continuity across every knot IsoParam curve
  SmBoolean bRtn = (   eContU >= SM_CT_G1
                    && eContV >= SM_CT_G1) ;

  return(bRtn) ;

} // end sm_AssertTestSurface4

