/*******************************************************************//**
PURPOSE  : AssertRule 5 - NonSingular Surface approximates a Singular Surface

  predicate = Are Sample Points along UVNaturalBoundary within Approx3dTol of one another
  action    =  Move all UVNaturalBoundary control Points to control Point centroid
***********************************************************************/
SmBoolean sm_AssertTestSurface5(const SmSurface *pSurface) // TRUE = okay, FALSE = problem
{
  ULONG lApproxSingularities ;
  ULONG lSingularities = pSurface->GetSingularities(NULL, NULL, &lApproxSingularities) ;

  // valid when surface has no ApproxSingularities
  SmBoolean bRtn = ((lApproxSingularities - lSingularities) == SM_SS_NONE) ; // same as  (lApproxSingularities & ~lSingularities) == SM_SS_NONE ;
                                                                             // because ApproxSingularities is set for every Singularities but not vice versa
  // all done
  return(bRtn) ;

} // end sm_AssertTestSurface5

