/*******************************************************************//**
PURPOSE  : AssertRule 6 - Surfaces can't have a non-seam closure [B605]
    I.e. no partial coincidence allowed on seam edges. 
    Does not look for internal G0 discontinuities, but those should be illegal.
    They are possible in offset surfaces.

  predicate = Surface is open, but boundaries are partially coincident
  action    = None. Invalid surface.
***********************************************************************/
SmBoolean sm_AssertTestSurface6(const SmSurface *pSurface) // TRUE = okay, FALSE = problem
{
    // Locals
    ULONG ii, jj;
    SmApproxTol3d    dATol    = SmTol::GetApproxTol3d( pSurface );
    const SmContext *pContext = pSurface->GetContext();

    // Compare opposite boundaries for overlap
    for ( ii = 0 ; ii < 2; ii++ )
    {
        // loop locals
        SmBoolean       bMoreWork = FALSE;
        SmBSplineCurve *pCrv1, *pCrv2;
        SmSolutionArray sSols;
        SmSurfParamType eSPType = SM_SP_U;

        // U direction 1st pass, V dir second.
        if ( ii == 1 )
        { eSPType = SM_SP_V; }

        // Okay if the surface is closed
        SmBoolean bClosed = pSurface->IsClosed( pSurface->GetNaturalUVDomain(), eSPType );
        if ( bClosed )
        { continue; }

        // Get iso parameter boundaries
        pSurface->CreateIsoBoundaries( *pContext, eSPType, dATol, pCrv1, pCrv2 );
        SmObjDelete sClean1( pCrv1 ), sClean2( pCrv2 );

        if ( pCrv1->IsDegenerate() || pCrv2->IsDegenerate() )
        { continue; }

        // Look for partial coincidence or G0 discontinuous
        SmXSectTol3d dXTol = SmTol::GetXSectTol3d( pCrv1, pCrv2 );
        pCrv1->GlobalCoincidenceChecker( pCrv1->GetNaturalInterval(), *pCrv2, pCrv2->GetNaturalInterval(), dXTol, bMoreWork, sSols );

        // Range of Values implies G0 discontinuous non-seam closure of surface
        for ( jj = 0; jj < sSols.GetSize(); jj++ )
        {
            SmSolution sSol = sSols[jj];
            if ( sSol.m_eSolutionType == SM_ST_RANGE_OF_VALUES )
            {
                return (FALSE);
            }
        } // end for each solution
    } // end for U dir, then V dir

    // Good Surfaces are closed or don't have a non-seam closure
    SmBoolean bRtn = TRUE;

    return( bRtn );

} // end sm_AssertTestSurface6

/*******************************************************************//**
PURPOSE: Check the validity of an SmSurface.

NOTES: Checks made:
// Remove Compoosite
//  - Type of m_pOwner, if present, is SmFace or SmCFace
 - Type of m_pOwner is SmFace or NULL
 - No parallel tangents at the corners
 - Not degenerate, to a point or curve
 - Is at least G1 in the interior and along boundaries

RETURNS ---  TRUE  = OK
             FALSE = Problem
***********************************************************************/
SmBoolean SmSurface::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL]
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests,
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests
                                    //      default:[SM_LEVEL_0]
  SmAssertWalking    eWalkTree,     // NotUsed: in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK]
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{
  SM_REF1(eWalkTree) ;
  // check base class validity
  SmBoolean bRtn = TRUE ;

  // call the base class AssertValid
  bRtn &= (  (eTestLevel != SM_LEVEL_GIVEN)
           ? SmAObject::AssertValid(pAList, eTestLevel, SM_NO_WALK, pTestRequests)
           : TRUE ) ;

  /*  0 */ // check type of SmSurface::m_pOwner
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0,
                                  (   m_pOwner == NULL
                                   || m_pOwner->IsKindOf(SmFace_TYPE)
// Remove Composite                 || m_pOwner->IsKindOf(SmCFace_TYPE)
                                   || m_pOwner->IsKindOf(SmOffsetSurface_TYPE) 
                                   || m_pOwner->IsKindOf(SmCrvOnSurf_TYPE)
                                   || m_pOwner->IsKindOf(SmSrfInVolume_TYPE) ), 
                                  _T("") ) ;

  // locals
  SmTol3d sOutTol3d ;
  double  dOutVal ;

  /*  1 */ // Surface Su and Sv Tangents in at least one corner are parallel (SM_EFF_ZERO_DEG)
  bRtn &= SM_ASSERT_VALUE_REPORT(1, SM_LEVEL_0, sm_AssertTestSurface1(this, &sOutTol3d, &dOutVal), sOutTol3d, dOutVal, _T("")) ;

  /*  2 */ // Surface should not degenerate into a point
  bRtn &= SM_ASSERT_VALUE_REPORT(2, SM_LEVEL_0, (!IsDegeneratePoint(SM_EFF_ZERO_DEG)), SM_EFF_ZERO_DEG, SM_UNDEF_DOUBLE, _T("")) ;

  /*  3 */ // Surface should not degenerate into a curve
  bRtn &= SM_ASSERT_VALUE_REPORT(3, SM_LEVEL_0, (!IsDegenerateCurve(SM_EFF_ZERO_DEG)), SM_EFF_ZERO_DEG, SM_UNDEF_DOUBLE, _T("")) ;

  /*  4 */ // Surface should not contain a G1 or C0 discontinuity
  bRtn &= SM_ASSERT_BOOLEAN_REPORT( 4, eTestLevel, sm_AssertTestSurface4(this), _T("") );

  /*  5 */ // NonSingular Surface approximates a Singular Surface
  bRtn &= SM_ASSERT_BOOLEAN_REPORT( 5, SM_LEVEL_0, sm_AssertTestSurface5(this), _T("") );

  /*  6 */ // Open surface has G0 discontinuities 
  bRtn &= SM_ASSERT_BOOLEAN_REPORT( 6, SM_LEVEL_0, sm_AssertTestSurface6(this), _T("") );

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  // draw
  if(bDebugMe)
    {
      Dump() ;

      SmOffsetSurface *pOffset  = GetFace() && GetFace()->IsKindOf(SmOffsetSurface_TYPE) ? (SmOffsetSurface *)GetFace() : NULL ;
      const SmSurface *pTgtSurf = pOffset ? pOffset : this ;
      SmFace          *pFace    = (pTgtSurf->GetFace() && pTgtSurf->GetFace()->IsKindOf(SmFace_TYPE)   ) ? (SmFace *)pTgtSurf->GetFace()    : NULL ;
      SmFaceuse       *pFaceuse = (pTgtSurf->GetFace() && pTgtSurf->GetFace()->IsKindOf(SmFaceuse_TYPE)) ? (SmFaceuse *)pTgtSurf->GetFace() : NULL ;
      SmBrep          *pBrep    =   pFace    ? pFace->GetBrep()
                                  : pFaceuse ? pFaceuse->GetBrep()
                                  :            NULL ;
      smgfx_Erase() ;
      smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(3,4, 1,0,0) ; Draw() ; sm_GraphicsLoop() ;
      smgfx_SetLook(3,4, 1,0,0) ; DrawUV() ; sm_GraphicsLoop() ;
      smgfx_SetLook(4,5, 0,1,0) ; if(pOffset) pOffset->DrawUV() ; sm_GraphicsLoop() ;
      smgfx_SetLook(5,6, 1,0,1) ; if(pFace) pFace->Draw() ; sm_GraphicsLoop() ;
      smgfx_SetLook(5,6, 1,0,1) ; if(pFaceuse) pFaceuse->Draw() ; sm_GraphicsLoop() ;
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done
  return( bRtn );

} // end SmSurface::AssertValid

