/*************************************************************
PURPOSE:  Get this surface number within brep

NOTES: The surface number is just the order within the
     brep topology.

**************************************************************/
ULONG SmSurface::GetSurfaceNumberInBrep()
 const
{
  ULONG lSurfaceNum = 0;

  SmFace *pF = (SmFace *)(this->GetFace());
  if(pF != NULL)
  {

    SmBrep *pBrep = pF->GetBrep();
    if(pBrep != NULL)
    {
      SmTArray<SmSurface*> sSurfaces;
      pBrep->GetSurfaces( sSurfaces );
      for(ULONG i = 0; i < sSurfaces.GetSize(); i++)
      {
        if(sSurfaces[i] == this)
        {
          lSurfaceNum = i;
          break;
        }
      }
    }
  }


  return(lSurfaceNum);
} // end SmSurface::GetSurfaceNumberInBrep

/*******************************************************************//**
PURPOSE:  Pretty print pointer values for this Shell showing how
             it connects to its owner Face or CFace
             in the topology graph.

NOTES: Only good for debugging because pointer values don't
                stay constant from run to run.
***********************************************************************/
void SmSurface::DumpTopology
  (ULONG lWalkDepth) // NotUsed: in :- surfaces are at the bottom of the topology graph
 const
{
  SM_REF1(lWalkDepth) ;
  // locals
  TCHAR        sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE] = {};

  // init sBuffToFile to NULL string for file output - this method is only for interactive screen output

  SmFace *pFaceOwner = (SmFace *)GetFace() ;

// Remove Composite
//  // swith on CFaces and Faces
  // swith on Face or NULL
  if(pFaceOwner == NULL)
    {
      smos_sprintf(sBuff,_T("%s"),_T("  Surface[0x%p] -> NOT CONNECTED TO FACE \n"), this) ;
      smos_WriteBuffer(sBuff, sBuffForFile);
    }
// Remove Composite
//  else if(pFaceOwner->IsKindOf(SmCFace_TYPE))
//    {
//      SM_ASSERT(pFaceOwner->GetSurface() == this) ;
//      smos_sprintf(sBuff,_T("  Surface[0x%p] -> CFace[0x%p] \n"), this, pFaceOwner) ;
//      smos_WriteBuffer(sBuff, sBuffForFile);
//    }
  else
    {
      SM_ASSERT(pFaceOwner->GetSurface() == this) ;
      smos_sprintf(sBuff,_T("  Surface[0x%p] -> Face[0x%p] \n"), this, pFaceOwner) ;
      smos_WriteBuffer(sBuff, sBuffForFile);

    }
} // end SmSurface::DumpTopology
